PAGES_DATA = [{'page_no': 1, 'title': "Into the Primitive: Buck's Sunny Domain", 'tr_title': "İlkel Dünyaya Doğru: Buck'ın Güneşli Diyarı", 'vocab_focus': [('domain', 'mülk, hakimiyet alanı'), ('ruler', 'hükümdar, efendi'), ('orchard', 'meyve bahçesi'), ('pasture', 'otlak, çayır'), ('companion', 'yoldaş, arkadaş'), ('aristocrat', 'soylu, asilzade'), ('stately', 'görkemli, vakur'), ('dignity', 'haysiyet, vakar')], 'sentences': [{'id': 1, 'text': 'Buck did not read the newspapers, or he would have known that trouble was brewing for every soft-muscled dog on the Pacific coast.', 'translation': 'Buck gazete okumuyordu; okusaydı Pasifik kıyısındaki yumuşak kaslı her köpek için büyük bir belanın yaklaştığını bilirdi.', 'notes': 'was brewing: mayalanıyordu / yaklaşıyordu.'}, {'id': 2, 'text': 'Men, groping in the Arctic darkness, had found a yellow metal, and thousands were rushing into the Northland.', 'translation': "Kutup karanlığında el yordamıyla arama yapan insanlar sarı bir metal bulmuştu ve binlercesi Kuzey Diyarı'na akın ediyordu.", 'notes': 'groping: el yordamıyla arayarak.'}, {'id': 3, 'text': 'These men needed heavy dogs with strong muscles to toil in the freezing cold and furry coats to protect them from the frost.', 'translation': 'Bu adamların dondurucu soğukta çalışacak güçlü kaslara ve ayazdan koruyacak kürk gibi kalın tüylere sahip iri köpeklere ihtiyacı vardı.', 'notes': 'to toil: ağır işte çalışmak.'}, {'id': 4, 'text': 'Buck lived at a big house in the sun-kissed Santa Clara Valley owned by Judge Miller.', 'translation': "Buck, güneşin öptüğü Santa Clara Vadisi'nde Yargıç Miller'a ait büyük bir köşkte yaşıyordu.", 'notes': 'sun-kissed: güneşle yıkanmış/öpülmüş.'}, {'id': 5, 'text': 'The house stood back from the road, half-hidden among the trees, through which glimpses could be caught of the wide veranda.', 'translation': 'Ev yoldan gerideydi; ağaçların arasında yarı gizlenmişti ve ağaçların arasından geniş verandanın manzarası yakalanabiliyordu.', 'notes': 'glimpses could be caught: manzaralar yakalanabiliyordu.'}, {'id': 6, 'text': 'There were great stables, green pastures, orchards of fruit trees, and deep wells of cool water.', 'translation': 'Orada devasa ahırlar, yemyeşil otlaklar, meyve bahçeleri ve serin su dolu derin kuyular vardı.', 'notes': 'great stables: devasa ahırlar.'}, {'id': 7, 'text': 'Over this great domain Buck ruled like an absolute monarch from the day he was born.', 'translation': 'Bu engin mülk üzerinde Buck, doğduğu günden itibaren mutlak bir hükümdar gibi hüküm sürdü.', 'notes': 'ruled like a monarch: hükümdar gibi yönetti.'}, {'id': 8, 'text': 'Here he was born, and here he had lived the four years of his happy life.', 'translation': 'Burada doğmuştu ve mutlu hayatının dört yılını burada geçirmişti.', 'notes': 'had lived: yaşamıştı (Past Perfect).'}, {'id': 9, 'text': 'It was true, there were other dogs, but they did not count against his majesty.', 'translation': 'Doğruydu, başka köpekler de vardı; fakat onun haşmeti karşısında hiçbir hükmü yoktu onların.', 'notes': 'did not count: sayılmazdı / hükmü yoktu.'}, {'id': 10, 'text': "His father, Elmo, a huge St. Bernard, had been the Judge's inseparable companion.", 'translation': "Babası, kocaman bir Saint Bernard olan Elmo, Yargıç'ın ayrılmaz yoldaşı olmuştu.", 'notes': 'inseparable: ayrılamaz, canciğer.'}, {'id': 11, 'text': "And Buck did not fail to maintain the dignity of his father's noble heritage.", 'translation': 'Ve Buck, babasının asil mirasının vakarını korumakta asla geri kalmadı.', 'notes': 'did not fail to: geri kalmadı / ihmal etmedi.'}, {'id': 12, 'text': 'His mother, Shep, had been a Scotch shepherd dog, giving him intelligence and agility.', 'translation': 'Annesi Shep ise ona zeka ve çeviklik kazandırmış bir İskoç çoban köpeğiydi.', 'notes': 'Scotch shepherd: İskoç çoban köpeği.'}, {'id': 13, 'text': 'He weighed one hundred and forty pounds, possessed of deep chest and muscular limbs.', 'translation': 'Yüz kırk pound ağırlığındaydı; derin bir göğse ve kaslı bacaklara sahipti.', 'notes': 'possessed of: ...e sahip.'}, {'id': 14, 'text': "He escorted the Judge's daughters on long twilight or early morning rambles.", 'translation': "Alacakaranlıkta veya sabahın erken saatlerinde yapılan uzun yürüyüşlerde Yargıç'ın kızlarına eşlik ederdi.", 'notes': 'rambles: kır yürüyüşleri.'}, {'id': 15, 'text': "On winter nights he lay at the Judge's feet before the roaring library fire.", 'translation': "Kış gecelerinde kütüphanedeki gürül gürül yanan ateşin önünde Yargıç'ın ayaklarının dibinde yatardı.", 'notes': 'roaring fire: gürül gürül yanan şömine.'}, {'id': 16, 'text': "He carried the Judge's grandsons upon his back and rolled them gently in the grass.", 'translation': "Yargıç'ın torunlarını sırtında taşır ve onları çimlerin üzerinde incitmeden yuvarlardı.", 'notes': 'rolled gently: nazikçe yuvarladı.'}, {'id': 17, 'text': 'He was neither a pampered house dog nor an outdoor kennel dog.', 'translation': 'Ne şımartılmış bir ev süs köpeğiydi ne de dışarıda kulübede beslenen sıradan bir bekçi köpeği.', 'notes': 'pampered: şımartılmış, el bebek gül bebek.'}, {'id': 18, 'text': 'Hunting, swimming, and outdoor life had hardened his muscles and invigorated his blood.', 'translation': 'Avlanmak, yüzmek ve açık hava hayatı kaslarını sertleştirmiş ve kanını canlandırmıştı.', 'notes': 'invigorated: canlandırdı, zindelik verdi.'}, {'id': 19, 'text': 'He walked with pride and confidence, knowing himself to be king of the valley.', 'translation': 'Kendisini vadinin kralı bilerek gururla ve güvenle yürürdü.', 'notes': 'knowing himself: kendini bilerek.'}, {'id': 20, 'text': 'But the year 1897 brought a dark shadow that would shatter his peaceful realm forever.', 'translation': 'Fakat 1897 yılı, onun bu huzurlu krallığını sonsuza dek yerle bir edecek karanlık bir gölge getirdi.', 'notes': 'shatter forever: sonsuza dek paramparça etmek.'}]}, {'page_no': 2, 'title': 'The Betrayal of Manuel', 'tr_title': "Manuel'in İhaneti ve Buck'ın Zincire Vurulması", 'vocab_focus': [('treachery', 'ihanet, kalleşlik'), ('gardener', 'bahçıvan'), ('gambling', 'kumar'), ('lottery', 'piyango'), ('strangle', 'boğmak, gırtlağını sıkmak'), ('cage', 'kafes'), ('fury', 'öfke, gazap'), ('kidnap', 'kaçırmak, hileyle götürmek')], 'sentences': [{'id': 21, 'text': "Manuel, one of the gardener's helpers, was an undesirable character with a destructive weakness.", 'translation': 'Bahçıvanın yardımcılarından biri olan Manuel, yıkıcı bir zaafı bulunan tekinsiz bir tipti.', 'notes': 'destructive weakness: yıkıcı zaaf.'}, {'id': 22, 'text': 'He loved to play the Chinese lottery and had a blind faith in his gambling system.', 'translation': 'Çin piyangosu oynamaya bayılırdı ve kendi kumar sistemine körü körüne bir inancı vardı.', 'notes': 'blind faith: körü körüne inanç.'}, {'id': 23, 'text': "To play a system requires money, while the wages of a gardener's helper barely feed a wife and children.", 'translation': 'Bir sistemi oynamak para gerektirirdi; oysa bir bahçıvan çırağının yevmiyesi bir eş ve çocukları ancak doyururdu.', 'notes': 'barely feed: ancak doyurur.'}, {'id': 24, 'text': "On the memorable night of Manuel's treachery, the Judge was at a meeting of the Raisin Growers' Association.", 'translation': "Manuel'in ihanet ettiği o unutulmaz gecede Yargıç, Kuru Üzüm Üreticileri Birliği'nin toplantısındaydı.", 'notes': 'memorable night: unutulmaz gece.'}, {'id': 25, 'text': 'The boys were busy at the athletic club, and nobody saw Manuel and Buck walk off through the orchard.', 'translation': "Gençler spor kulübünde meşguldü ve meyve bahçesinden geçerek uzaklaşan Manuel ile Buck'ı hiç kimse görmedi.", 'notes': 'walk off: yürüyüp gitmek.'}, {'id': 26, 'text': 'Buck had learned to trust the men he knew, and presumed this was merely an evening stroll.', 'translation': 'Buck tanıdığı adamlara güvenmeyi öğrenmişti ve bunun yalnızca bir akşam gezintisi olduğunu sandı.', 'notes': 'presumed: varsaydı, sandı.'}, {'id': 27, 'text': 'No one saw them arrive at the little flag station known as College Park.', 'translation': 'College Park olarak bilinen küçük tren durağına vardıklarını kimse görmedi.', 'notes': 'flag station: küçük ara durak.'}, {'id': 28, 'text': 'A stranger stood waiting in the shadows, talking in low whispers with the treacherous helper.', 'translation': 'Gölgelerin içinde bekleyen bir yabancı, o hain yardımcıyla alçak sesli fısıltılarla konuşuyordu.', 'notes': 'treacherous helper: hain yardımcı.'}, {'id': 29, 'text': "Money chinked in Manuel's hand as he handed a stout piece of rope to the stranger.", 'translation': 'Manuel sağlam bir urgan parçasını yabancıya uzatırken elinde madeni paralar şıngırdadı.', 'notes': 'stout piece of rope: sağlam urgan.'}, {'id': 30, 'text': 'Before Buck could understand, the heavy rope was tied swiftly and tightly around his neck.', 'translation': 'Buck ne olduğunu anlayamadan, kalın urgan hızla ve sımsıkı boynuna dolandı.', 'notes': 'tied swiftly: hızla bağlandı.'}, {'id': 31, 'text': 'He growled in fierce surprise and leaped forward to assert his authority.', 'translation': 'Şiddetli bir şaşkınlıkla hırladı ve otoritesini göstermek için ileriye sıçradı.', 'notes': 'assert his authority: otoritesini göstermek.'}, {'id': 32, 'text': 'The rope tightened painfully around his throat, cutting off his wind and choking him into darkness.', 'translation': 'Urgan boğazına acıyla kenetlendi; nefesini keserek onu karanlığın içinde boğdu.', 'notes': 'cutting off wind: nefesini keserek.'}, {'id': 33, 'text': 'In his life he had never been treated so, and never had he been so shockingly enraged.', 'translation': 'Ömründe kendisine hiç böyle davranılmamıştı ve hiç böylesine dehşet verici biçimde öfkelenmemişti.', 'notes': 'shockingly enraged: fena halde öfkelenmiş.'}, {'id': 34, 'text': 'He struggled with all his strength, but the rope choked him until his senses faded away.', 'translation': 'Bütün gücüyle çırpındı, fakat urgan bilinci silinene kadar onu nefessiz bıraktı.', 'notes': 'senses faded: bilinci silindi.'}, {'id': 35, 'text': 'When he recovered consciousness, he was lying on the floor of an express train baggage car.', 'translation': 'Yeniden bilincine kavuştuğunda, bir ekspres trenin bagaj vagonunun zemininde yatıyordu.', 'notes': 'recovered consciousness: bilinci yerine geldi.'}, {'id': 36, 'text': 'A thick brass wire bound his jaw shut, preventing him from biting his captors.', 'translation': 'Kalın bir pirinç tel çenesini sımsıkı bağlamış, kendisini kaçıranları ısırmasını engelliyordu.', 'notes': 'bound jaw shut: çenesini bağlı tuttu.'}, {'id': 37, 'text': 'For two days and nights the train sped north, while Buck suffered without water or food.', 'translation': 'Tren iki gün ve iki gece boyunca kuzeye doğru hızla ilerledi; bu sürede Buck aç ve susuz acı çekti.', 'notes': 'suffered without water: susuz acı çekti.'}, {'id': 38, 'text': 'A roaring fever burned in his throat, and his fiery eyes blazed with uncontrollable wrath.', 'translation': 'Boğazında kavurucu bir ateş yanıyordu ve alev alev gözleri zapt edilemez bir öfkeyle parlıyordu.', 'notes': 'uncontrollable wrath: zapt edilemez gazap.'}, {'id': 39, 'text': 'He had transformed from an aristocratic house ruler into a raging demon seeking vengeance.', 'translation': 'Evdeki o soylu efendiden, intikam arayan kükreyen bir iblise dönüşmüştü.', 'notes': 'seeking vengeance: intikam arayan.'}, {'id': 40, 'text': 'Finally, the train came to a halt in a strange city where he was dragged into a high-walled shed.', 'translation': 'Sonunda tren yabancı bir şehirde durdu; burada Buck yüksek duvarlı bir barakaya sürüklendi.', 'notes': 'high-walled shed: yüksek duvarlı baraka.'}]}, {'page_no': 3, 'title': 'The Man in the Red Sweater and the Law of the Club', 'tr_title': 'Kırmızı Kazaklı Adam ve Sopa Kanunu', 'vocab_focus': [('sweater', 'kazak'), ('club', 'kalın sopa, lobut'), ('hatchet', 'küçük balta, nacak'), ('splinter', 'kıymık, talaş'), ('ferocious', 'vahşi, yırtıcı'), ('subdue', 'boyun eğdirmek, bastırmak'), ('primitive', 'ilkel, ilkçağa ait'), ('conqueror', 'fatih, galip gelen')], 'sentences': [{'id': 41, 'text': 'A stout man with a red sweater signed a book for the express messenger and unlocked the door.', 'translation': 'Kırmızı kazaklı tıknaz bir adam ekspres kurye için bir defteri imzaladı ve kapının kilidini açtı.', 'notes': 'stout man: tıknaz adam.'}, {'id': 42, 'text': 'Buck was inside a heavy wooden crate, his tongue swollen and his throat parched with thirst.', 'translation': 'Buck ağır ahşap bir sandığın içindeydi; dili şişmiş ve boğazı susuzluktan kurumuştu.', 'notes': 'parched with thirst: susuzluktan kavrulmuş.'}, {'id': 43, 'text': 'The man brought a hatchet and a heavy club into the shed and approached the crate.', 'translation': 'Adam barakaya bir balta ve ağır bir sopa getirdi ve sandığa yaklaştı.', 'notes': 'heavy club: ağır sopa.'}, {'id': 44, 'text': '"Now, you red-eyed devil," said the man softly, driving the hatchet into the wooden slats.', 'translation': '"Şimdi seni kızıl gözlü iblis seni," dedi adam sakince, baltayı tahta çıtalara vurarak.', 'notes': 'wooden slats: tahta çıtalar.'}, {'id': 45, 'text': 'As the wood splintered, Buck hurled himself against the bars, roaring in desperate fury.', 'translation': 'Ahşap parçalandıkça Buck kendini çaresiz bir öfkeyle kükreyerek parmaklıklara vurdu.', 'notes': 'as wood splintered: tahta parçalandıkça.'}, {'id': 46, 'text': 'His coat was bristling, his fangs were bared, and white foam flecked his bloody lips.', 'translation': 'Tüyleri diken dikendi, dişleri meydandaydı ve beyaz köpükler kanlı dudaklarına sıçrıyordu.', 'notes': 'fangs were bared: dişleri meydandaydı.'}, {'id': 47, 'text': 'With a final wrench of the hatchet, the opening was made, and Buck sprang forward like a lion.', 'translation': 'Baltanın son bir kanırtmasıyla delik açıldı ve Buck bir aslan gibi öne fırladı.', 'notes': 'wrench: burkma, kanırtma.'}, {'id': 48, 'text': 'Midway in his spring, a heavy blow from the club crashed against his head.', 'translation': 'Daha havadayken, sopadan inen ağır bir darbe başına çarptı.', 'notes': 'midway in his spring: sıçrayışının tam ortasında.'}, {'id': 49, 'text': 'He was hurled to the ground, stunned and gasping, his teeth clicking together from the impact.', 'translation': 'Afallamış ve nefesi kesilmiş halde yere savruldu; darbenin şiddetinden dişleri birbirine çarptı.', 'notes': 'hurled to ground: yere savruldu.'}, {'id': 50, 'text': 'Never had he been struck by a weapon; in his sunny realm men did not carry clubs.', 'translation': 'Ömründe hiç bir silahla vurulmamıştı; onun güneşli diyarında insanlar sopa taşımazlardı.', 'notes': 'struck by a weapon: silahla vurulmuş.'}, {'id': 51, 'text': 'Again he sprang, and again the club descended with smashing, merciless force.', 'translation': 'Bir kez daha sıçradı ve sopa bir kez daha ezici, acımasız bir güçle üzerine indi.', 'notes': 'descended: indi (darbe).'}, {'id': 52, 'text': 'Twelve times he charged, and twelve times the club shattered his leap and brought him to the dust.', 'translation': 'On iki defa hücum etti ve on iki defa sopa onun sıçrayışını kırarak onu toza toprağa serdi.', 'notes': 'brought to dust: toza toprağa serdi.'}, {'id': 53, 'text': 'At last he lay unconscious, bleeding from nose and mouth and ears, unable to rise.', 'translation': 'Sonunda burnundan, ağzından ve kulaklarından kanlar süzülerek ayağa kalkamaz halde baygın yattı.', 'notes': 'unable to rise: kalkamaz halde.'}, {'id': 54, 'text': '"Answers to the name of Buck," the man remarked, reading from the invoice.', 'translation': '"Buck adına karşılık verir," dedi adam faturadan okuyarak.', 'notes': 'invoice: fatura, irsaliye.'}, {'id': 55, 'text': '"Well, Buck, my boy," he said gently, "we\'ve had our little bout, and the best thing you can do is to drop it."', 'translation': '"Pekala Buck evlat," dedi tatlı bir sesle, "ufak güreşimizi yaptık ve yapabileceğin en akıllıca şey uslu durmak."', 'notes': 'had our bout: güreşimizi/maçımızı yaptık.'}, {'id': 56, 'text': '"You\'ve learned your place, and I know mine; be a good dog and all\'ll go well."', 'translation': '"Sen yerini öğrendin, ben de kendiminkini biliyorum; uslu bir köpek olursan her şey yolunda gider."', 'notes': 'learned your place: haddini/yerini öğrendin.'}, {'id': 57, 'text': 'The man brought a bowl of fresh water, which Buck lapped up eagerly, and a generous piece of raw meat.', 'translation': 'Adam bir kap taze su getirdi; Buck bunu hevesle yalayıp bitirdi; ardından cömert bir parça çiğ et verdi.', 'notes': 'lapped up eagerly: hevesle yaladı.'}, {'id': 58, 'text': 'Buck was beaten, but he was not broken; his spirit was bruised, but not destroyed.', 'translation': 'Buck yenilmişti ama kırılmamıştı; ruhu yaralanmıştı ama yok edilmemişti.', 'notes': 'beaten but not broken: yenilmiş ama kırılmamış.'}, {'id': 59, 'text': 'He had learned the great primitive law: a man with a club was a lawgiver, a master to be obeyed.', 'translation': 'O büyük ilkel kanunu öğrenmişti: elinde sopa tutan adam bir kanun koyucuydu, itaat edilmesi gereken bir efendiydi.', 'notes': 'lawgiver: kanun koyucu.'}, {'id': 60, 'text': 'That club was his introduction into the reign of primitive law, and he accepted the lesson without surrender.', 'translation': 'O sopa, onun ilkel kanunlar çağına girişi oldu ve teslim olmadan bu dersi aklına kazıdı.', 'notes': 'without surrender: teslim olmaksızın.'}]}, {'page_no': 4, 'title': 'Journey North on the Narwhal', 'tr_title': 'Narwhal Gemisiyle Kuzeye Yolculuk ve İlk Kar', 'vocab_focus': [('steamer', 'buharlı gemi'), ('deck', 'güverte'), ('propeller', 'gemi pervanesi'), ('swarthy', 'esmer, yanık tenli'), ('government', 'hükümet'), ('dispatch', 'resmi evrak, posta'), ('fairness', 'adalet, hakkaniyet'), ('flake', 'kar tanesi')], 'sentences': [{'id': 61, 'text': 'Two men came to the shed one morning to inspect the newly arrived dogs.', 'translation': 'Bir sabah yeni gelen köpekleri incelemek üzere barakaya iki adam geldi.', 'notes': 'inspect: denetlemek, incelemek.'}, {'id': 62, 'text': 'One was a little swarthy French-Canadian named Perrault, and the other was a giant half-breed named Francois.', 'translation': 'Biri Perrault adında esmer, ufak tefek bir Fransız Kanadalıydı; diğeri ise Francois adında dev yapılı bir melezdi.', 'notes': 'swarthy: esmer, yanık tenli.'}, {'id': 63, 'text': '"Sacredam!" cried Perrault, examining Buck with knowledgeable hands. "Dat one damn bully dog, eh?"', 'translation': '"Vay canına!" diye haykırdı Perrault, anlayan ellerle Buck\'ı yoklayarak. "Şu harika, güçlü bir köpek ama değil mi?"', 'notes': 'bully dog: güçlü/mükemmel köpek (argo övgü).'}, {'id': 64, 'text': 'They paid three hundred dollars for him, a price that proved his extraordinary value.', 'translation': 'Onun için üç yüz dolar ödediler; bu da onun olağanüstü değerini kanıtlayan bir fiyattı.', 'notes': 'extraordinary value: olağanüstü değer.'}, {'id': 65, 'text': 'They were couriers for the Canadian Government, carrying urgent dispatches into the frozen Yukon Territory.', 'translation': "Kanada Hükümeti'nin ulaklarıydılar; donmuş Yukon Bölgesi'ne acil resmi evrakları taşıyorlardı.", 'notes': 'urgent dispatches: acil resmi postalar.'}, {'id': 66, 'text': 'Buck was taken aboard the steamship Narwhal and led down into the chilly hold.', 'translation': 'Buck Narwhal buharlı gemisine bindirildi ve soğuk ambarına indirildi.', 'notes': 'chilly hold: soğuk gemi ambarı.'}, {'id': 67, 'text': 'There he joined other dogs: Curly, a good-natured Newfoundland, and Spitz, a big, snow-white husky from Spitsbergen.', 'translation': "Orada diğer köpeklere katıldı: iyi huylu bir Newfoundland olan Curly ve Spitsbergen'den gelen bembeyaz, iri bir husky olan Spitz.", 'notes': 'good-natured: iyi huylu.'}, {'id': 68, 'text': "Spitz was friendly in an oily, treacherous way, smiling even while planning to steal a companion's food.", 'translation': 'Spitz yılışık, sinsi bir dostluk sergiliyordu; bir arkadaşının yemeğini çalmayı planlarken bile gülümsüyordu.', 'notes': 'oily, treacherous: yılışık ve sinsi.'}, {'id': 69, 'text': 'Also aboard was Dave, a gloomy, morose dog who wanted only to be left entirely alone.', 'translation': 'Ayrıca gemide, sadece tamamen kendi haline bırakılmak isteyen kasvetli, asık suratlı bir köpek olan Dave de vardı.', 'notes': 'morose: asık suratlı, aksi.'}, {'id': 70, 'text': 'Day after day the propeller churned the grey northern seas, carrying them closer to the Arctic circle.', 'translation': 'Günler geçtikçe pervane gri kuzey denizlerini köpürterek onları Kutup dairesine daha da yaklaştırdı.', 'notes': 'propeller churned: pervane köpürttü.'}, {'id': 71, 'text': 'Each day the air grew colder and sharper, biting into their warm coats.', 'translation': 'Her geçen gün hava daha soğuk ve daha keskin hale geliyor, sıcak kürklerini ısırıyordu.', 'notes': 'grew colder: daha da soğudu.'}, {'id': 72, 'text': 'Finally, the engines stopped, and the dogs were brought up onto the open deck.', 'translation': 'Sonunda motorlar sustu ve köpekler açık güverteye çıkarıldı.', 'notes': 'open deck: açık güverte.'}, {'id': 73, 'text': "Buck's first step on the beach at Dyea felt astonishingly strange and cold beneath his paws.", 'translation': 'Dyea sahilinde attığı ilk adım, patilerinin altında şaşırtıcı derecede yabancı ve soğuk hissettirdi.', 'notes': 'astonishingly: şaşırtıcı şekilde.'}, {'id': 74, 'text': 'He stepped into something soft and white, and sank into it like mud, but it was freezing cold.', 'translation': 'Yumuşak ve beyaz bir şeyin üzerine bastı ve çamur gibi içine battı, fakat buz gibi soğuktu bu.', 'notes': 'sank into it: içine battı.'}, {'id': 75, 'text': 'He leaped back with a snort, shaking his paws in bewilderment.', 'translation': 'Şaşkınlık içinde patilerini silkeleyerek bir homurtuyla geriye sıçradı.', 'notes': 'in bewilderment: şaşkınlıkla.'}, {'id': 76, 'text': 'More of this white stuff was falling gently from the grey sky overhead.', 'translation': 'Yukarıdaki gri gökyüzünden bu beyaz şeyden usul usul daha fazla dökülüyordu.', 'notes': 'overhead: yukarıda, başın üstünde.'}, {'id': 77, 'text': 'He bit at a falling flake, and it vanished upon his warm tongue like magic.', 'translation': 'Düşen bir kar tanesine bir ısırık attı ve tanecik sıcak dilinin üzerinde sihir gibi yok oldu.', 'notes': 'vanished like magic: büyü gibi yok oldu.'}, {'id': 78, 'text': 'He tried again and again, causing the onlookers on the beach to roar with laughter.', 'translation': 'Tekrar tekrar denedi; bu da sahildeki izleyicilerin kahkahalarla kükremesine yol açtı.', 'notes': 'roar with laughter: kahkahayla kükremek.'}, {'id': 79, 'text': 'He was ashamed, he knew not why, for it was his very first experience with snow.', 'translation': 'Neden olduğunu bilmeden utandı, zira bu onun karla olan ilk deneyimiydi.', 'notes': 'first experience: ilk tecrübe.'}, {'id': 80, 'text': 'Here in this frozen wilderness, all civilised customs were left behind, and raw survival began.', 'translation': 'Burada, bu donmuş yaban hayatında tüm medeni alışkanlıklar geride bırakıldı ve yalın hayatta kalma mücadelesi başladı.', 'notes': 'raw survival: yalın/katıksız hayatta kalma.'}]}, {'page_no': 5, 'title': 'The Law of Club and Fang', 'tr_title': "Sopa ve Diş Kanunu: Curly'nin Trajik Sonu", 'vocab_focus': [('savage', 'vahşi, ilkel'), ('husky', 'eskimo köpeği, husky'), ('brutal', 'acımasız, gaddar'), ('carnivorous', 'etobur'), ('snarl', 'diş gösterip hırlamak'), ('tragedy', 'trajedi, acı son'), ('nightmare', 'kabus'), ('remorseless', 'merhametsiz, acımasız')], 'sentences': [{'id': 81, 'text': "Buck's first day on the Dyea beach was like a nightmare of savage fury and sudden violence.", 'translation': "Buck'ın Dyea sahilindeki ilk günü vahşi bir öfkenin ve ani şiddetin kabusu gibiydi.", 'notes': 'savage fury: vahşi öfke.'}, {'id': 82, 'text': 'Every hour was filled with shock and surprise, shattering the peace of his former life.', 'translation': 'Her saati şok ve sürprizlerle doluydu; önceki hayatının huzurunu paramparça ediyordu.', 'notes': 'shattering: paramparça eden.'}, {'id': 83, 'text': 'He was suddenly jerked from the heart of civilization into the heart of things primordial.', 'translation': 'Medeniyetin kalbinden bir anda koparılıp ilkçağın o ilkel dünyasının bağrına fırlatılmıştı.', 'notes': 'things primordial: ilkçağa ait şeyler.'}, {'id': 84, 'text': 'These dogs and men were not town dogs and town men; they knew only the law of club and fang.', 'translation': 'Bu köpekler ve bu adamlar kasaba köpeği veya kasaba insanı değildi; sadece sopa ve diş kanununu bilirlerdi.', 'notes': 'law of club and fang: sopa ve diş kanunu.'}, {'id': 85, 'text': 'Curly, the friendly Newfoundland, was the first to suffer the terrible reality of this law.', 'translation': 'Dost canlısı Newfoundland Curly, bu kanunun korkunç gerçeğini ilk tadan talihsiz oldu.', 'notes': 'first to suffer: ilk çeken/tadan.'}, {'id': 86, 'text': 'She made friendly advances toward a husky half her size, wishing to play upon the snow.', 'translation': 'Karda oynamak isteyerek kendi cüssesinin yarısı kadar olan bir huskyye dostça yaklaştı.', 'notes': 'friendly advances: dostça yaklaşımlar.'}, {'id': 87, 'text': 'Without warning, the wolf-dog struck like a coiled spring, slashing her face from eye to jaw.', 'translation': "Hiçbir uyarı olmaksızın kurt köpeği kurulu bir yay gibi fırladı; Curly'nin yüzünü gözünden çenesine kadar yardı.", 'notes': 'slashing: kesip yararak.'}, {'id': 88, 'text': 'It was the wolf manner of fighting: to strike and leap away, to slash and tear.', 'translation': 'Bu, kurtların dövüş tarzıydı: vurup geri sıçramak, yarıp parçalamak.', 'notes': 'wolf manner: kurt tarzı.'}, {'id': 89, 'text': 'Instantly, thirty or forty other huskies gathered in a silent, watchful circle around the combatants.', 'translation': 'Anında, otuz kırk kadar diğer husky dövüşenlerin etrafında sessiz, tetikte bir çember oluşturdu.', 'notes': 'silent, watchful circle: sessiz, pürdikkat çember.'}, {'id': 90, 'text': 'Curly rushed her antagonist in honest indignation, but the husky struck her again and sprang aside.', 'translation': 'Curly dürüst bir öfkeyle hasmının üzerine atıldı, fakat husky ona bir kez daha vurup kenara sıçradı.', 'notes': 'honourable indignation: haklı öfke.'}, {'id': 91, 'text': 'As she turned, her hind feet slipped on the packed snow, and she tumbled upon her side.', 'translation': 'Dönerken arka ayakları sıkışmış karda kaydı ve yan tarafının üzerine yuvarlandı.', 'notes': 'packed snow: ezilmiş/sert kar.'}, {'id': 92, 'text': 'That was what the silent circle had been waiting for with gleaming eyes and dripping fangs.', 'translation': 'Işıldayan gözleri ve damlayan dişleriyle o sessiz çemberin beklediği tam da buydu işte.', 'notes': 'gleaming eyes: parıldayan gözler.'}, {'id': 93, 'text': 'They closed in upon her, snarling and yelping, burying her beneath a bristling mass of bodies.', 'translation': 'Hırlayarak ve havlayarak üzerine çullandılar; onu diken diken olmuş tüylü gövdelerden bir yığının altına gömdüler.', 'notes': 'closed in upon: üzerine çullandılar.'}, {'id': 94, 'text': 'So sudden and terrible was the attack that Buck was rooted to the spot in horror.', 'translation': 'Saldırı öylesine ani ve korkunçtu ki Buck dehşet içinde olduğu yere çakılıp kaldı.', 'notes': 'rooted to the spot: olduğu yere çivilenmiş.'}, {'id': 95, 'text': 'Francois leaped into the melee with an axe, while Perrault slashed furiously with clubs.', 'translation': 'Francois elinde bir baltayla kargaşanın içine daldı; Perrault ise sopalarla vahşice savurdu.', 'notes': 'leaped into melee: arbedeye daldı.'}, {'id': 96, 'text': "They beat off the bloodthirsty pack, but it took less than two minutes to end Curly's life.", 'translation': "O kana susamış sürüyü defettiler, fakat Curly'nin canını almak iki dakikadan az sürmüştü.", 'notes': 'bloodthirsty pack: kana susamış sürü.'}, {'id': 97, 'text': 'There lay Curly, torn to pieces and lifeless upon the blood-stained snow.', 'translation': 'Curly kana bulanmış karların üzerinde paramparça edilmiş ve cansız bir vaziyette yatıyordu.', 'notes': 'blood-stained: kana bulanmış.'}, {'id': 98, 'text': 'The scene often came back to Buck to trouble him in his sleep.', 'translation': "Bu sahne uykusunda onu rahatsız etmek üzere sık sık Buck'ın aklına geri gelirdi.", 'notes': 'often came back: sık sık geri geldi.'}, {'id': 99, 'text': 'So that was the way: once down, you were finished, torn to ribbons by your comrades.', 'translation': 'Demek kural buydu: bir kez yere düştün mü işin bitmişti; yoldaşların tarafından didik didik parçalanırdın.', 'notes': 'once down: bir kez düştün mü.'}, {'id': 100, 'text': 'He saw Spitz run out his scarlet tongue and laugh, and from that moment Buck hated him with deadly hatred.', 'translation': "Spitz'in al dilini dışarı çıkarıp güldüğünü gördü ve o andan itibaren Buck ondan ölümcül bir nefretle nefret etti.", 'notes': 'deadly hatred: ölümcül nefret.'}]}, {'page_no': 6, 'title': 'In the Traces and the Sled Harness', 'tr_title': 'Kızağa Koşulma ve Koşum İplerindeki Çetin Eğitim', 'vocab_focus': [('harness', 'koşum takımı'), ('trace', 'koşum kayışı, çekme ipi'), ('sled', 'kızak'), ('whip', 'kamçı'), ('buckle', 'toka, bağlamak'), ('expert', 'uzman, usta'), ('reproach', 'kınama, azar'), ('monotonous', 'monoton, tekdüze')], 'sentences': [{'id': 101, 'text': "Before Buck had recovered from the shock of Curly's death, another shock awaited him.", 'translation': "Buck Curly'nin ölümünün şokunu henüz atlatamamışken onu bir başka şok bekliyordu.", 'notes': 'recovered from: ...den toparlanmak.'}, {'id': 102, 'text': 'Francois buckled upon him an arrangement of straps and buckles made of stout leather.', 'translation': 'Francois, sağlam deriden yapılmış bir kayış ve toka düzeneğini onun üzerine bağladı.', 'notes': 'stout leather: sağlam deri.'}, {'id': 103, 'text': 'It was a harness, such as he had seen the workhorses wear back in the Santa Clara orchards.', 'translation': 'Tıpkı Santa Clara bahçelerinde iş atlarının giydiğini gördüğü türden bir koşum takımıydı bu.', 'notes': 'workhorses: iş/çiftlik atları.'}, {'id': 104, 'text': 'His dignity was wounded at being made a draught animal, but he was too wise to rebel against the club.', 'translation': 'Bir çeki hayvanı haline getirilmekten ötürü gururu yaralandı, fakat sopaya isyan etmeyecek kadar akıllıydı.', 'notes': 'draught animal: çeki hayvanı.'}, {'id': 105, 'text': 'He was placed in the traces between Dave, the gloomy wheeler, and Spitz, the experienced leader.', 'translation': "Kasvetli tekerlek köpeği Dave ile tecrübeli lider Spitz'in arasındaki çekme kayışlarına yerleştirildi.", 'notes': 'wheeler: kızağa en yakın güçlü çeki köpeği.'}, {'id': 106, 'text': 'Francois cracked his whip, shouting: "Mush! Ho! Ho!"', 'translation': 'Francois kamçısını şaklattı ve haykırdı: "Deh! Haydi! Haydi!"', 'notes': 'mush: kızak köpeklerini sürme komutu.'}, {'id': 107, 'text': 'The heavy sled moved forward across the snow, and Buck leaped into the work with all his energy.', 'translation': 'Ağır kızak karların üzerinden ileriye doğru hareket etti ve Buck tüm enerjisiyle işe asıldı.', 'notes': 'leaped into work: işe var gücüyle sarıldı.'}, {'id': 108, 'text': 'Though he was inexperienced, he learned with astonishing quickness from his harsh teachers.', 'translation': 'Deneyimsiz olmasına rağmen, o sert öğretmenlerinden şaşırtıcı bir çabuklukla öğrendi.', 'notes': 'astonishing quickness: şaşırtıcı çabukluk.'}, {'id': 109, 'text': 'Dave nipped his hindquarters whenever he made an awkward turn or slackened his pull.', 'translation': 'Acemice bir dönüş yaptığında veya çekişini gevşettiğinde Dave onun butlarını hafifçe ısırırdı.', 'notes': 'slackened his pull: çekişini gevşetti.'}, {'id': 110, 'text': 'Spitz, snarling from the front, corrected his direction with sharp reprimands.', 'translation': 'Önden hırlayan Spitz, sert uyarılarla onun rotasını anında düzeltirdi.', 'notes': 'reprimands: azarlamalar, uyarılar.'}, {'id': 111, 'text': "And Francois's whip fell without pity whenever Buck failed to heed the warnings of his mates.", 'translation': "Ve Buck yoldaşlarının uyarılarına kulak asmadığı her an Francois'in kamçısı acımasızca üzerine inerdi.", 'notes': 'failed to heed: kulak asmadı.'}, {'id': 112, 'text': 'Two new dogs were added to the team: Billee and Joe, two true huskies who were brothers.', 'translation': 'Takıma iki yeni köpek daha eklendi: öz kardeş olan iki hakiki husky, Billee ve Joe.', 'notes': 'true huskies: safkan huskyler.'}, {'id': 113, 'text': 'Billee was excessively good-natured, while Joe was sour, introspective, and forever snarling.', 'translation': 'Billee aşırı derecede iyi huyluydu; Joe ise huysuz, içine kapanık ve sürekli hırlayan biriydi.', 'notes': 'introspective: içine kapanık.'}, {'id': 114, 'text': 'Then came Sol-leks, an old, battle-scarred husky with one eye who demanded only not to be approached on his blind side.', 'translation': 'Ardından tek gözü olan, savaş yaralarıyla dolu, yalnızca kör tarafından kendisine yaklaşılmamasını isteyen yaşlı bir husky olan Sol-leks geldi.', 'notes': 'battle-scarred: savaş yaralarıyla dolu.'}, {'id': 115, 'text': 'When Buck unwittingly walked on his blind side, Sol-leks slashed his shoulder with lightning speed.', 'translation': 'Buck farkında olmadan onun kör tarafından yürüdüğünde, Sol-leks şimşek hızıyla omzunu yardı.', 'notes': 'unwittingly: farkında olmadan, bilmeyerek.'}, {'id': 116, 'text': 'Buck never made that mistake again; his education in northern diplomacy was progressing rapidly.', 'translation': 'Buck o hatayı bir daha asla yapmadı; kuzey diplomasisindeki eğitimi hızla ilerliyordu.', 'notes': 'northern diplomacy: kuzey diplomasisi (mecaz).'}, {'id': 117, 'text': 'They hauled heavy government supplies up the canyon trail, climbing the dreaded Chilkoot Pass.', 'translation': "Korkulan Chilkoot Geçidi'ni tırmanarak kanyon patikası boyunca ağır hükümet erzaklarını çektiler.", 'notes': 'dreaded pass: korkulan geçit.'}, {'id': 118, 'text': 'Day after day they toiled against freezing winds and sheer glaciers of solid ice.', 'translation': 'Günler boyu dondurucu rüzgarlara ve som buzdan dik buzullara karşı kan ter içinde çabaladılar.', 'notes': 'sheer glaciers: dimdik buzullar.'}, {'id': 119, 'text': "Buck's muscles became hard as iron, and his pads grew tough enough to resist the razor-sharp crust of the snow.", 'translation': "Buck'ın kasları demir gibi sertleşti ve pati tabanları karın jilet gibi keskin kabuğuna direnecek kadar nasırlaştı.", 'notes': 'razor-sharp crust: jilet gibi kabuk.'}, {'id': 120, 'text': 'He was fitting himself for the great struggle of life in the silent, frozen North.', 'translation': "Sessiz, donmuş Kuzey'deki o büyük hayat mücadelesine kendini adım adım hazırlıyordu.", 'notes': 'fitting himself: kendini hazırlıyordu.'}]}, {'page_no': 7, 'title': 'The Dominant Primordial Beast', 'tr_title': 'İçteki İlkel Kurdun Uyanışı ve Kar Yuvası', 'vocab_focus': [('burrow', 'kovuk açmak, karı kazıp girmek'), ('instinct', 'içgüdü'), ('primordial', 'ilkel, ilkçağa ait'), ('ancestor', 'ata, soy'), ('rations', 'kumanya, tayın'), ('morality', 'ahlak'), ('survive', 'hayatta kalmak'), ('dormant', 'uykuda olan, gizli kalmış')], 'sentences': [{'id': 121, 'text': 'The first night on the trail presented Buck with the urgent problem of finding shelter.', 'translation': "Patikadaki ilk gece, Buck'ı acil bir barınak bulma sorunuyla karşı karşıya bıraktı.", 'notes': 'urgent problem: acil sorun.'}, {'id': 122, 'text': 'The tent was pitched, but when he tried to enter, Francois and Perrault bombarded him with kitchen utensils.', 'translation': 'Çadır kurulmuştu, fakat içeri girmeye çalıştığında Francois ve Perrault onu mutfak kap kacağıyla bombardımana tuttular.', 'notes': 'bombarded: bombardımana tuttular.'}, {'id': 123, 'text': 'He wandered freezing in the snow, the wind chilling him to the bone, wondering where the other dogs were.', 'translation': 'Rüzgar onu iliklerine kadar dondururken karların arasında üşüyerek dolaştı; diğer köpeklerin nerede olduğunu merak ederek.', 'notes': 'wandered freezing: donarak dolaştı.'}, {'id': 124, 'text': 'Suddenly the snow gave way beneath his forelegs, and something squirmed warm under his feet.', 'translation': 'Birdenbire ön bacaklarının altındaki kar çöktü ve ayaklarının altında sıcak bir şey kıpırdandı.', 'notes': 'gave way: çöktü, yol verdi.'}, {'id': 125, 'text': 'He leaped back, but a friendly whimper told him it was Billee, curled tight in a hole under the snow.', 'translation': 'Geriye sıçradı, fakat dostça bir inilti ona bu kişinin kar altındaki bir çukura kıvrılmış Billee olduğunu söyledi.', 'notes': 'curled tight: sımsıkı kıvrılmış.'}, {'id': 126, 'text': 'Another lesson! So that was the way they slept in this freezing country!', 'translation': 'Bir ders daha! Demek bu buz kesen memlekette böyle uyuyorlardı!', 'notes': 'that was the way: yol buydu işte.'}, {'id': 127, 'text': 'Buck promptly excavated a hole for himself, curled up, and fell into a warm, comfortable sleep.', 'translation': 'Buck derhal kendine bir çukur kazdı, içine kıvrıldı ve sıcacık, rahat bir uykuya daldı.', 'notes': 'excavated a hole: bir çukur kazdı.'}, {'id': 128, 'text': 'When he awoke next morning, a heavy blanket of fresh snow had sealed him completely in.', 'translation': 'Ertesi sabah uyandığında, kalın bir taze kar örtüsü onu tamamen içeri hapsetmişti.', 'notes': 'sealed in: içeri mühürlemişti.'}, {'id': 129, 'text': 'For a moment terror gripped him, thinking he was trapped, but he broke through into the daylight.', 'translation': 'Tuzak kurulduğunu sanarak bir an dehşet onu sardı, fakat karı yarıp gün ışığına çıktı.', 'notes': 'broke through: yarıp çıktı.'}, {'id': 130, 'text': 'His food consisted of a pound and a half of dried salmon, which never satisfied his ravenous hunger.', 'translation': 'Yiyeceği bir buçuk pound kurutulmuş somondan ibaretti ve bu, onun açlıktan kıvranan midesini asla doyurmuyordu.', 'notes': 'ravenous hunger: kurt gibi açlık.'}, {'id': 131, 'text': 'He saw another dog, Pike, sneak a piece of bacon from the grub-box while the drivers looked away.', 'translation': 'Sürücüler başka yöne bakarken, Pike adlı diğer köpeğin erzak sandığından bir parça domuz pastırması aşırdığını gördü.', 'notes': 'sneak a piece: gizlice bir parça aşırmak.'}, {'id': 132, 'text': 'The next day Buck duplicated the performance, getting away with a whole chunk of bacon undetected.', 'translation': 'Ertesi gün Buck bu marifeti tekrarladı ve koca bir parça pastırmayı fark edilmeden kapıp kaçtı.', 'notes': 'duplicated performance: marifeti tekrarladı.'}, {'id': 133, 'text': 'A great outcry followed, but an innocent dog, Dub, was punished instead of him.', 'translation': 'Büyük bir yaygara koptu, fakat onun yerine masum bir köpek olan Dub cezalandırıldı.', 'notes': 'great outcry: büyük yaygara.'}, {'id': 134, 'text': 'This robbery marked Buck as fit to survive in the hostile Northland environment.', 'translation': "Bu hırsızlık, Buck'ın çetin Kuzey Diyarı ortamında hayatta kalmaya uygun olduğunu gösterdi.", 'notes': 'fit to survive: hayatta kalmaya uygun.'}, {'id': 135, 'text': 'Civilized moral codes of property and right had no place where survival was at stake.', 'translation': 'Hayatta kalmanın söz konusu olduğu yerde, medeniyetin mülkiyet ve hak ahlakına yer yoktu.', 'notes': 'at stake: tehlikede/söz konusu.'}, {'id': 136, 'text': 'He did not steal for the joy of it, but because the clamour of his stomach demanded it.', 'translation': 'Keyif olsun diye çalmıyordu; midesinin o yakıcı feryadı bunu emrettiği için çalıyordu.', 'notes': 'clamour of stomach: midenin feryadı.'}, {'id': 137, 'text': 'His ancient instincts, dormant through generations of soft domestic life, awoke with fierce power.', 'translation': 'Nesiller boyu süren uysal evcil hayatta uykuda kalmış kadim içgüdüleri vahşi bir güçle uyandı.', 'notes': 'dormant instincts: uykudaki içgüdüler.'}, {'id': 138, 'text': 'He could smell the wind, forecast the weather by the stars, and sense every change of the trail.', 'translation': 'Rüzgarın kokusunu alabiliyor, yıldızlara bakarak havayı tahmin edebiliyor ve patikadaki her değişikliği seziyordu.', 'notes': 'forecast: önceden tahmin etmek.'}, {'id': 139, 'text': 'The domesticated gentleman was dead; the primitive wolf inside him was rising.', 'translation': 'O evcilleşmiş beyefendi ölmüştü; içindeki ilkel kurt artık ayağa kalkıyordu.', 'notes': 'was rising: yükseliyordu/uyanıyordu.'}, {'id': 140, 'text': 'And in the quiet of the freezing nights, he pointed his nose at the moon and howled the ancient wolf song.', 'translation': 'Ve dondurucu gecelerin sessizliğinde burnunu aya doğru dikti ve kadim kurt ezgisini uludu.', 'notes': 'howled the wolf song: kurt şarkısını uludu.'}]}, {'page_no': 8, 'title': 'The Attack of the Starving Huskylar', 'tr_title': 'Aç Yabani Köpeklerin Gece Baskını ve Kanlı Savaş', 'vocab_focus': [('famine', 'kıtlık, açlık'), ('marauder', 'yağmacı, çapulcu'), ('skeleton', 'iskelet gibi zayıf'), ('slash', 'kesip yarmak'), ('onslaught', 'şiddetli saldırı, hücum'), ('frenzy', 'cinnet, çılgınlık hali'), ('scatter', 'etrafa dağılmak'), ('wound', 'yara, yaralamak')], 'sentences': [{'id': 141, 'text': 'The camp was pitched one evening on the shores of Lake Le Barge in a biting blizzard.', 'translation': "Bir akşam kamp, dondurucu bir tipi altında Le Barge Gölü'nün kıyısında kuruldu.", 'notes': 'pitched: kuruldu (çadır).'}, {'id': 142, 'text': 'Suddenly, without warning, four or five score of starving huskies invaded the camp from an Indian village.', 'translation': 'Ansızın, hiçbir uyarı olmaksızın, bir Kızılderili köyünden gelen dört beş düzine aç husky kampı bastı.', 'notes': 'score: yirmi (four score = seksen).'}, {'id': 143, 'text': 'They were walking skeletons, maddened by the smell of food and desperate with hunger.', 'translation': 'Yiyecek kokusuyla çıldırmış ve açlıktan gözü dönmüş ayaklı birer iskelettiler.', 'notes': 'walking skeletons: ayaklı iskeletler.'}, {'id': 144, 'text': 'They poured into the camp, ravenous and ferocious, their fangs gleaming in the firelight.', 'translation': 'Ateşin ışığında dişleri parıldayarak, açgözlü ve yırtıcı bir halde kampa akın ettiler.', 'notes': 'poured into: akın ettiler.'}, {'id': 145, 'text': 'Perrault and Francois fought with their heavy clubs, but the starving brutes felt no pain.', 'translation': 'Perrault ve Francois ağır sopalarıyla savaştılar, fakat açlıktan gözü dönmüş bu hayvanlar hiçbir acı hissetmiyordu.', 'notes': 'felt no pain: acı hissetmedi.'}, {'id': 146, 'text': 'They chewed through leather straps, devoured canvas tarpaulins, and leaped at the team dogs.', 'translation': 'Deri kayışları çiğneyip kopardılar, brandaları mideye indirdiler ve kızak köpeklerinin üzerine atıldılar.', 'notes': 'devoured: yiyip yuttu.'}, {'id': 147, 'text': 'Buck was attacked by three gaunt monsters simultaneously, slashing his throat and shoulders.', 'translation': 'Buck boğazını ve omuzlarını yaran bir deri bir kemik kalmış üç canavarın aynı andaki saldırısına uğradı.', 'notes': 'simultaneously: eşzamanlı olarak.'}, {'id': 148, 'text': 'He fought furiously, ripping flesh with his fangs and hurling attackers back into the snow.', 'translation': 'Dişleriyle etleri kopararak ve saldırganları karların içine geri savurarak vahşice savaştı.', 'notes': 'ripping flesh: et kopararak.'}, {'id': 149, 'text': 'Dave and Sol-leks fought back-to-back, bristling like porcupines, clearing a circle of blood.', 'translation': 'Dave ve Sol-leks kirpi gibi tüylerini kabartıp sırt sırta vererek kanlı bir çember açarak savaştılar.', 'notes': 'back-to-back: sırt sırta.'}, {'id': 150, 'text': 'Joe snapped like a demon, while Billee fled weeping through the woods in sheer panic.', 'translation': 'Joe bir iblis gibi dişlerini birbirine çarptı; Billee ise katıksız bir panikle ağlayarak ormana doğru kaçtı.', 'notes': 'sheer panic: katıksız panik.'}, {'id': 151, 'text': 'In the midst of the chaos, Spitz saw an opportunity to destroy his growing rival.', 'translation': 'Bu kargaşanın ortasında Spitz, giderek büyüyen rakibini yok etmek için bir fırsat gördü.', 'notes': 'growing rival: büyüyen rakip.'}, {'id': 152, 'text': "He attacked Buck from the side, driving his fangs into Buck's neck while Buck fought the invaders.", 'translation': "Buck istilacılarla savaşırken Spitz yandan saldırdı ve dişlerini Buck'ın boynuna geçirdi.", 'notes': 'from the side: yandan.'}, {'id': 153, 'text': 'Buck shook him off, raging at this treacherous assault in the dark.', 'translation': 'Karanlıktaki bu kalleşçe saldırı karşısında çılgına dönen Buck onu silkeleyip attı.', 'notes': 'treacherous assault: haince saldırı.'}, {'id': 154, 'text': 'The team was driven into the forest, scattered and bleeding, waiting for daylight.', 'translation': 'Kızak takımı ormanın içine doğru sürüldü; darmadağınık ve kan revan içinde gün ışığını beklediler.', 'notes': 'driven into: sürüklendi/sürüldü.'}, {'id': 155, 'text': 'When morning came, they limped back to camp, wounded, battered, and exhausted.', 'translation': 'Sabah olduğunda yaralı, hırpalanmış ve bitkin bir halde topallayarak kampa döndüler.', 'notes': 'limped back: topallayarak döndü.'}, {'id': 156, 'text': 'Not an inch of food remained in the camp; the sled lashings had been gnawed to threads.', 'translation': 'Kampta tek lokma yiyecek kalmamıştı; kızak bağları çiğnenip iplik iplik edilmişti.', 'notes': 'gnawed to threads: kemirilip iplik haline getirilmiş.'}, {'id': 157, 'text': 'Every dog was wounded: Dub was limping, and Sol-leks had lost his other eye partially.', 'translation': 'Her köpek yaralıydı: Dub topallıyordu ve Sol-leks diğer gözünü de kısmen kaybetmişti.', 'notes': 'partially: kısmen.'}, {'id': 158, 'text': '"Sacredam!" Perrault groaned, inspecting their supplies. "It will take us three weeks to reach Dawson!"', 'translation': '"Lanet olsun!" diye inledi Perrault erzaklarını kontrol ederken. "Dawson\'a varmamız üç haftamızı alacak!"', 'notes': 'take three weeks: üç hafta sürmek.'}, {'id': 159, 'text': '"And what if those wild devils give them madness?" added Francois anxiously.', 'translation': '"Ya o vahşi iblisler bizim köpeklere kuduz bulaştırdıysa?" diye endişeyle ekledi Francois.', 'notes': 'give madness: kuduz bulaştırmak.'}, {'id': 160, 'text': 'Yet they repaired the harness, tightened the traces, and set off once more into the desolate white expanse.', 'translation': 'Yine de koşumları onardılar, ipleri sıktılar ve o ıssız beyaz genişliğe doğru bir kez daha yola koyuldular.', 'notes': 'set off once more: bir kez daha yola koyuldular.'}]}, {'page_no': 9, 'title': 'The Deadly Trail of Thirty Mile River', 'tr_title': "Otuz Mil Nehri'nin İnce Buzu ve Minik Deri Mokasenler", 'vocab_focus': [('crevasse', 'buzul yarığı, çatlak'), ('submerge', 'suya batmak'), ('perilous', 'ölümcül, çok tehlikeli'), ('moccasin', 'deri mokasen çorap/patik'), ('thaw', 'erimek, buz çözülmesi'), ('endurance', 'dayanıklılık, tahammül'), ('frostbite', 'donma, soğuk ısırması'), ('courage', 'cesaret, metanet')], 'sentences': [{'id': 161, 'text': 'Thirty Mile River was a treacherous ribbon of wild water barely skin-coated with fragile ice.', 'translation': 'Otuz Mil Nehri, üzerinde ancak incecik kırılgan bir buz tabakası bulunan tekinsiz bir vahşi su şeridiydi.', 'notes': 'barely skin-coated: zar zor ince bir tabakayla kaplı.'}, {'id': 162, 'text': 'Underneath, the furious current rushed at six miles an hour, ready to swallow any living creature.', 'translation': 'Buzun altında saatte altı mil hızla akan hırçın akıntı, canlı her yaratığı yutmaya hazır bekliyordu.', 'notes': 'furious current: hırçın akıntı.'}, {'id': 163, 'text': 'Perrault walked ahead with a long pole, constantly tapping the ice to test its strength.', 'translation': 'Perrault elinde uzun bir sırıkla önden yürüyor; sağlamlığını sınamak için buza durmadan vuruyordu.', 'notes': 'tapping: tıklatarak, hafifçe vurarak.'}, {'id': 164, 'text': 'A dozen times he broke through, saved only by holding the pole horizontally across the hole.', 'translation': 'Düzinelerce kez buzu kırıp suya düştü; ancak sırığı deliğin üzerine yatay tutarak canını kurtardı.', 'notes': 'broke through: kırıp içine düştü.'}, {'id': 165, 'text': 'Each time he fell in, they had to build an immediate fire to dry his frozen garments.', 'translation': 'Suya her düştüğünde, donmuş giysilerini kurutmak için derhal bir ateş yakmak zorunda kaldılar.', 'notes': 'build an immediate fire: acilen ateş yakmak.'}, {'id': 166, 'text': 'At fifty degrees below zero, wet boots meant losing feet to frostbite within an hour.', 'translation': 'Sıfırın altında elli derecede, ıslak çizmeler bir saat içinde ayakları soğuktan kaybetmek demekti.', 'notes': 'frostbite: donma/soğuk yanığı.'}, {'id': 167, 'text': 'Once, the whole sled broke through, dragging Dave and Buck into the churning black water.', 'translation': "Bir keresinde bütün kızak buzu kırdı; Dave ve Buck'ı köpüren kara suların içine sürükledi.", 'notes': 'churning water: köpüren su.'}, {'id': 168, 'text': 'They were hauled out half-drowned, their coats instantly turning into solid armor of ice.', 'translation': 'Yarı boğulmuş halde çekip çıkarıldılar; kürkleri anında som bir buz zırhına dönüştü.', 'notes': 'armor of ice: buzdan zırh.'}, {'id': 169, 'text': 'Francois ran them around the roaring fire until the ice thawed and was scraped from their fur.', 'translation': 'Buzlar eriyip kürklerinden kazınana kadar Francois onları gürül gürül yanan ateşin etrafında koşturdu.', 'notes': 'scraped from fur: kürkten kazındı.'}, {'id': 170, 'text': "Buck's feet were softer than the huskies', having grown up on the warm lawns of California.", 'translation': "Kaliforniya'nın sıcak çimlerinde büyüdüğünden, Buck'ın patileri huskylerinkinden çok daha yumuşaktı.", 'notes': 'warm lawns: sıcak çimler.'}, {'id': 171, 'text': 'The razor-sharp ice crust cut his pads until he limped in agony at the end of each day.', 'translation': 'Jilet gibi keskin buz kabuğu pati tabanlarını yardı; öyle ki her günün sonunda acı içinde topallıyordu.', 'notes': 'limped in agony: ızdırap içinde topalladı.'}, {'id': 172, 'text': 'He refused to rise for his supper unless Francois brought the dried fish directly to his bed.', 'translation': 'Francois kurutulmuş balığı doğrudan yattığı yere getirmedikçe akşam yemeği için ayağa kalkmayı reddediyordu.', 'notes': 'refused to rise: kalkmayı reddetti.'}, {'id': 173, 'text': 'Seeing his distress, the kind-hearted Frenchman cut four tiny moccasins from his own buckskin jacket.', 'translation': 'Onun bu perişan halini gören iyi yürekli Fransız, kendi geyik derisi ceketinden dört minik mokasen patik kesti.', 'notes': 'buckskin jacket: geyik derisi ceket.'}, {'id': 174, 'text': "Every morning Francois lovingly tied the little moccasins upon Buck's four aching feet.", 'translation': "Her sabah Francois bu küçük patikleri Buck'ın sızlayan dört patisine sevgiyle bağladı.", 'notes': 'lovingly tied: sevgiyle bağladı.'}, {'id': 175, 'text': 'Buck looked ridiculous at first, marching stiffly like a soldier on parade, but he loved them.', 'translation': 'Törendeki bir asker gibi kaskatı yürüyerek ilk başta gülünç görünüyordu, fakat bu patiklere bayıldı.', 'notes': 'looked ridiculous: gülünç görünüyordu.'}, {'id': 176, 'text': 'One morning Francois forgot them, and Buck lay on his back, waving his four paws in protest.', 'translation': 'Bir sabah Francois onları unuttu; Buck ise sırtüstü yatıp dört patisini protesto edercesine havada salladı.', 'notes': 'waving in protest: itirazla sallayarak.'}, {'id': 177, 'text': 'Francois laughed, knelt down, and tied them on before Buck would take a single step.', 'translation': 'Francois güldü, diz çöktü ve Buck tek bir adım bile atmadan önce onları bağladı.', 'notes': 'knelt down: diz çöktü.'}, {'id': 178, 'text': 'Later, his pads hardened like leather, and the moccasins were discarded upon the trail.', 'translation': 'Daha sonra pati tabanları kösele gibi sertleşti ve mokasenler patikada bir kenara bırakıldı.', 'notes': 'hardened like leather: kösele gibi sertleşti.'}, {'id': 179, 'text': 'Through sheer determination, they conquered the Thirty Mile River in six days of unbroken toil.', 'translation': "Katıksız bir azimle, altı günlük kesintisiz bir çabayla Otuz Mil Nehri'ni dize getirdiler.", 'notes': 'sheer determination: katıksız kararlılık.'}, {'id': 180, 'text': 'Every mile brought Buck closer to his destined reckoning with the treacherous Spitz.', 'translation': "Alınan her mil, Buck'ı o hain Spitz ile yaşayacağı mukadder hesaplaşmaya bir adım daha yaklaştırdı.", 'notes': 'destined reckoning: mukadder hesaplaşma.'}]}, {'page_no': 10, 'title': 'The Covert Mutiny Against Spitz', 'tr_title': "Spitz'e Karşı Gizli İsyan ve Sarsılan Liderlik", 'vocab_focus': [('mutiny', 'isyan, başkaldırı'), ('rivalry', 'rekabet'), ('subversive', 'düzen bozucu, kışkırtıcı'), ('bully', 'zorba, kabadayı'), ('discipline', 'disiplin, intizam'), ('anarchy', 'kargaşa, anarşi'), ('hegemony', 'egemenlik, hakimiyet'), ('feud', 'kan davası, amansız düşmanlık')], 'sentences': [{'id': 181, 'text': 'Nothing moved Spitz so much as the quiet, deliberate rebellion of Buck.', 'translation': "Spitz'i hiçbir şey Buck'ın o sessiz, planlı başkaldırısı kadar öfkelendiremezdi.", 'notes': 'deliberate rebellion: kasıtlı/planlı isyan.'}, {'id': 182, 'text': "Buck had never picked a fight, but he stood squarely in the path of the white leader's tyranny.", 'translation': 'Buck hiçbir zaman kavgayı başlatan olmadı, fakat beyaz liderin zorbalığının tam karşısında dimdik durdu.', 'notes': 'stood squarely: dimdik durdu.'}, {'id': 183, 'text': "He openly shielded other dogs from Spitz's unprovoked wrath.", 'translation': "Spitz'in sebepsiz gazabına karşı diğer köpekleri açıkça koruyup siper oldu.", 'notes': 'shielded from: ...den korudu.'}, {'id': 184, 'text': 'When Spitz attacked the timid Billee, Buck sprang between them, driving Spitz back with bared fangs.', 'translation': "Spitz o çekingen Billee'ye saldırdığında Buck ikisinin arasına daldı; dişlerini göstererek Spitz'i geri püskürttü.", 'notes': 'sprang between: aralarına atıldı.'}, {'id': 185, 'text': "A covert mutiny grew within the team under Buck's silent encouragement.", 'translation': "Buck'ın sessiz cesaretlendirmesiyle kızak takımının içinde gizli bir isyan filizlendi.", 'notes': 'covert mutiny: gizli isyan.'}, {'id': 186, 'text': 'Pike refused to pull in his traces, and Dub shirked his duties openly.', 'translation': 'Pike kayışlarını çekmeyi reddetti ve Dub görevlerinden açıkça kaytarmaya başladı.', 'notes': 'shirked his duties: görevlerinden kaytardı.'}, {'id': 187, 'text': 'Whenever Spitz tried to discipline them, Buck intervened, defying his authority.', 'translation': 'Spitz onları terbiye etmeye kalkıştığında Buck araya giriyor, onun otoritesine meydan okuyordu.', 'notes': 'defying authority: otoriteye meydan okuyarak.'}, {'id': 188, 'text': 'Francois saw the danger brewing and kept his heavy whip constantly in motion.', 'translation': 'Francois yaklaşan tehlikeyi gördü ve ağır kamçısını durmaksızın havada şaklatıp durdu.', 'notes': 'kept in motion: sürekli hareket halinde tuttu.'}, {'id': 189, 'text': '"One of dese days dat Buck gwine jump on Spitz and chew him all up!" Francois warned Perrault.', 'translation': '"Günün birinde bu Buck Spitz\'in üstüne atlayıp onu kıtır kıtır yiyecek!" diye uyardı Francois Perrault\'yu.', 'notes': 'chew all up: kıtır kıtır yemek.'}, {'id': 190, 'text': '"Dat Spitz big fighter, but Buck two times bigger and mad like hell," the driver answered.', 'translation': '"Şu Spitz yaman dövüşçü, ama Buck iki katı daha iri ve cehennem gibi öfkeli," diye yanıtladı sürücü.', 'notes': 'mad like hell: cehennem gibi öfkeli.'}, {'id': 191, 'text': 'Discipline broke down completely; the dogs quarrelled constantly and snarled at the harness.', 'translation': 'Disiplin tamamen çöktü; köpekler durmadan kavga ediyor ve koşum takımlarına hırlıyordu.', 'notes': 'broke down: çöktü, bozuldu.'}, {'id': 192, 'text': 'Anarchy reigned where orderly cooperation had once ruled the trail.', 'translation': 'Patikada bir zamanlar düzenli bir işbirliğinin hüküm sürdüğü yerde şimdi anarşi kol geziyordu.', 'notes': 'anarchy reigned: kargaşa hüküm sürdü.'}, {'id': 193, 'text': 'Dave and Sol-leks alone remained unmoved, caring only for the dignity of their daily toil.', 'translation': 'Yalnızca Dave ve Sol-leks istiflerini bozmadı; sadece günlük emeklerinin onurunu önemsiyorlardı.', 'notes': 'remained unmoved: istifini bozmadı.'}, {'id': 194, 'text': 'For them the traces were sacred, and they had no time for petty squabbles.', 'translation': 'Onlar için çekme ipleri kutsaldı ve ufak tefek didişmelere ayıracak vakitleri yoktu.', 'notes': 'petty squabbles: ufak tefek didişmeler.'}, {'id': 195, 'text': 'Spitz felt his supremacy slipping away, and his cold eyes watched Buck with murderous intent.', 'translation': "Spitz liderliğinin ellerinden kayıp gittiğini hissediyordu ve soğuk gözleri Buck'ı katilce niyetlerle izliyordu.", 'notes': 'supremacy slipping: üstünlüğün kayması.'}, {'id': 196, 'text': 'He knew that only a fight to the death could decide the master of the team.', 'translation': 'Takımın efendisinin ancak ölümüne bir kavgayla belirlenebileceğini çok iyi biliyordu.', 'notes': 'fight to the death: ölümüne kavga.'}, {'id': 197, 'text': 'Buck knew it too, and he waited calmly for the inevitable moment.', 'translation': 'Buck da bunu biliyordu ve o kaçınılmaz anı büyük bir sükunetle bekledi.', 'notes': 'inevitable moment: kaçınılmaz an.'}, {'id': 198, 'text': 'Between them lay an unbridgeable gulf of ancient hatred and primordial ambition.', 'translation': 'Aralarında kadim nefretten ve ilkçağ hırsından örülü kapanmaz bir uçurum uzanıyordu.', 'notes': 'unbridgeable gulf: kapatılamaz uçurum.'}, {'id': 199, 'text': 'The pride of the trail and the glory of the lead belonged to one dog alone.', 'translation': 'Patikanın onuru ve liderliğin şerefi yalnızca tek bir köpeğe ait olabilirdi.', 'notes': 'glory of the lead: liderlik şerefi.'}, {'id': 200, 'text': 'The final clash arrived on a freezing night beneath the pale luminescence of the northern moon.', 'translation': 'Son çarpışma, kuzey ayının solgun ışıltısı altında dondurucu bir gecede çıkageldi.', 'notes': 'final clash: son çarpışma.'}]}, {'page_no': 11, 'title': 'The Death Struggle in the Snow', 'tr_title': 'Kar Tavşanı Kovalamacası ve Spitz ile Ölüm Kalım Düellosu', 'vocab_focus': [('hare', 'kar tavşanı, yaban tavşanı'), ('instinct', 'avlanma içgüdüsü'), ('pursuit', 'kovalama, takip'), ('duel', 'düello, teke tek dövüş'), ('slash', 'yırtmak, derin kesik açmak'), ('parry', 'savuşturmak, darbeyi savmak'), ('bone', 'kemik'), ('merciless', 'merhametsiz, acımasız')], 'sentences': [{'id': 201, 'text': 'A snowshoe hare leaped from the brush one night, and sixty dogs dashed across the snow in frantic pursuit.', 'translation': 'Bir gece çalıların arasından bir kar tavşanı fırladı ve altmış köpek çılgınca bir takiple karların üzerinde koştu.', 'notes': 'snowshoe hare: kar tavşanı.'}, {'id': 202, 'text': 'Buck led the great hunting pack, baying with the joy of the blood-lust awakened in his heart.', 'translation': 'Yüreğinde uyanan kan arzusunun sevinciyle uluyarak bu büyük av sürüsüne Buck öncülük etti.', 'notes': 'blood-lust: kan dökme arzusu/şehveti.'}, {'id': 203, 'text': 'Spitz cut across a narrow strip of land, heading off the hare and snapping its back with a single crunch.', 'translation': 'Spitz dar bir kara parçasını kestirmeden geçip tavşanın önünü kesti ve tek bir çatırtıyla belini kırdı.', 'notes': 'heading off: önünü keserek.'}, {'id': 204, 'text': "Buck crashed into him with all his momentum, but Spitz rolled upright, slashing Buck's shoulder.", 'translation': "Buck bütün hızıyla ona çarptı, fakat Spitz hemen ayağa fırlayarak Buck'ın omzunu yardı.", 'notes': 'rolled upright: toparlanıp ayağa kalktı.'}, {'id': 205, 'text': 'In an instant, the fifty other huskies formed a silent, expectant circle around the two fighters.', 'translation': 'Bir anda diğer elli husky, iki dövüşçünün etrafında sessiz, beklenti dolu bir çember kurdu.', 'notes': 'expectant circle: beklenti dolu çember.'}, {'id': 206, 'text': 'This was the duel to the death: the fallen dog would never rise from the snow.', 'translation': 'Bu, ölümüne bir düelloydu: yere düşen köpek karlardan bir daha asla ayağa kalkamayacaktı.', 'notes': 'duel to the death: ölümüne düello.'}, {'id': 207, 'text': 'Spitz was a seasoned fighter, parrying every strike and slashing like a fencing master.', 'translation': 'Spitz usta bir eskrimci gibi her darbeyi savuşturan ve yarıp geçen tecrübeli bir dövüşçüydü.', 'notes': 'fencing master: eskrim ustası.'}, {'id': 208, 'text': 'Time after time Buck charged, and time after time Spitz tore his flesh and sprang clear.', 'translation': 'Buck defalarca hücum etti ve Spitz defalarca onun etini parçalayıp yana kaçtı.', 'notes': 'time after time: defalarca.'}, {'id': 209, 'text': 'Buck was bleeding from a dozen wounds, panting heavily as the cold air froze his breath.', 'translation': 'Soğuk hava nefesini dondururken Buck bir düzine yaradan kan kaybediyor, ağır ağır soluyordu.', 'notes': 'bleeding from wounds: yaralardan kanayan.'}, {'id': 210, 'text': 'The circle of huskies drew closer, their tongues lolling out, waiting for the final collapse.', 'translation': 'Dilleri dışarı sarkmış halde huskylerin çemberi giderek daraldı; o son yere yığılışı bekleyerek.', 'notes': 'tongues lolling out: dilleri dışarı sarkarak.'}, {'id': 211, 'text': 'Buck possessed a quality that made for greatness: imagination.', 'translation': 'Buck, büyüklüğü yaratan o eşsiz niteliğe sahipti: zeka ve taktik hayal gücü.', 'notes': 'made for greatness: büyüklük sağlayan.'}, {'id': 212, 'text': "He feigned another rush at Spitz's throat, but at the last second dove low for the snow.", 'translation': "Spitz'in boğazına doğru yeni bir hamle yapar gibi sahte bir hücum yaptı, fakat son saniyede karların üzerine alçaldı.", 'notes': 'feigned another rush: başka bir hücum taklidi yaptı.'}, {'id': 213, 'text': "His jaws snapped together upon Spitz's left foreleg, and the clean snap of bone echoed in the silence.", 'translation': "Çeneleri Spitz'in sol ön bacağına kenetlendi ve kemiğin net kırılma sesi sessizlikte yankılandı.", 'notes': 'clean snap of bone: kemiğin temiz kırılışı.'}, {'id': 214, 'text': 'Spitz staggered on three legs, crying out in sudden terror and agonizing pain.', 'translation': 'Spitz ani bir dehşet ve dayanılmaz bir acıyla haykırarak üç bacağı üzerinde yalpaladı.', 'notes': 'staggered: yalpaladı, sendeledi.'}, {'id': 215, 'text': 'Before the white dog could recover, Buck charged again and broke his right foreleg.', 'translation': 'Beyaz köpek toparlanamadan Buck bir kez daha yüklendi ve onun sağ ön bacağını da kırdı.', 'notes': 'broke right foreleg: sağ ön bacağını kırdı.'}, {'id': 216, 'text': 'Spitz fell upon his knees, the fighting spirit extinguished from his glazing eyes.', 'translation': 'Dövüşme azmi buğulanan gözlerinden silinip giden Spitz dizlerinin üzerine çöktü.', 'notes': 'glazing eyes: donuklaşan gözler.'}, {'id': 217, 'text': 'There was no mercy; the law of club and fang demanded total destruction of the defeated.', 'translation': 'Merhamet yoktu; sopa ve diş kanunu yenilenin tamamen yok edilmesini emrediyordu.', 'notes': 'demanded destruction: yok edilmeyi talep etti.'}, {'id': 218, 'text': 'Buck delivered the final crushing blow, and Spitz rolled helplessly onto his back.', 'translation': 'Buck o son ezici darbeyi indirdi ve Spitz çaresizce sırtüstü devrildi.', 'notes': 'crushing blow: ezici darbe.'}, {'id': 219, 'text': 'The dark circle of sixty wolves closed in like a black tidal wave, and Spitz vanished forever.', 'translation': 'Altmış kurttan oluşan karanlık çember kara bir medcezir dalgası gibi kapandı ve Spitz sonsuza dek yok oldu.', 'notes': 'black tidal wave: kara medcezir dalgası.'}, {'id': 220, 'text': 'Buck stood motionless in the moonlight, the dominant primordial beast that had made its kill.', 'translation': 'Buck ay ışığının altında öylece hareketsiz durdu; avını yapmış o egemen ilkel canavarın ta kendisiydi artık.', 'notes': 'dominant primordial beast: egemen ilkel canavar.'}]}, {'page_no': 12, 'title': 'Buck Takes the Lead', 'tr_title': "Buck'ın Liderliği Ele Geçirmesi ve Rekor Dawson Koşusu", 'vocab_focus': [('lead', 'liderlik, öncülük'), ('heritage', 'miras, hak'), ('whip', 'kamçı'), ('club', 'sopa'), ('command', 'kumanda etmek, emretmek'), ('record', 'rekor'), ('solidarity', 'dayanışma, birlik'), ('pride', 'gurur, iftihar')], 'sentences': [{'id': 221, 'text': '"Eh? What did I say? Spitz gone for sure!" cried Francois the next morning, looking at the empty snow.', 'translation': '"Ha? Ben ne demiştim? Spitz kesin gitmiş!" diye haykırdı ertesi sabah boş karlara bakan Francois.', 'notes': 'gone for sure: kesin gitmiş.'}, {'id': 222, 'text': "He brought Sol-leks to the leader's position, intending to give the old veteran the harness.", 'translation': "Koşumları o eski kıdemliye verme niyetiyle Sol-leks'i liderin yerine getirdi.", 'notes': 'old veteran: ihtiyar kıdemli.'}, {'id': 223, 'text': 'Buck bounded into the place, growling low, refusing to yield the position he had won.', 'translation': 'Buck kazandığı yeri teslim etmeyi reddederek alçak bir hırıltıyla liderin yerine fırladı.', 'notes': 'refusing to yield: teslim etmeyi reddederek.'}, {'id': 224, 'text': '"Get out of dat!" shouted Francois, threatening him with a club.', 'translation': '"Çık oradan çabuk!" diye bağırdı Francois, onu sopayla tehdit ederek.', 'notes': 'threatening: tehdit ederek.'}, {'id': 225, 'text': 'Buck retreated out of reach of the club, but refused to let any other dog take the lead.', 'translation': 'Buck sopanın erişemeyeceği bir mesafeye çekildi, fakat başka hiçbir köpeğin liderliği almasına izin vermedi.', 'notes': 'out of reach: erişim dışı.'}, {'id': 226, 'text': 'For an hour Francois chased him with clubs and whips, but Buck circled lithely beyond his grasp.', 'translation': 'Bir saat boyunca Francois sopalar ve kamçılarla onun peşinde koştu, fakat Buck onun menzilinin dışında kıvrakça döndü.', 'notes': 'circled lithely: kıvrakça döndü.'}, {'id': 227, 'text': 'He demanded his rightful place as king of the traces; nothing less would satisfy his iron will.', 'translation': 'Kayışların kralı olarak hakkı olan yeri talep ediyordu; onun çelik iradesini bundan daha azı tatmin edemezdi.', 'notes': 'iron will: demir irade.'}, {'id': 228, 'text': 'Perrault laughed and looked at his watch: "We waste time! Put him in de lead, Francois!"', 'translation': 'Perrault güldü ve saatine baktı: "Vakit kaybediyoruz! Geçir onu başa Francois!"', 'notes': 'waste time: vakit kaybetmek.'}, {'id': 229, 'text': "Francois threw down his club, and Buck trot forward proudly to receive the leader's harness.", 'translation': 'Francois sopasını yere attı ve Buck gururla tırıs giderek liderin koşum takımını teslim aldı.', 'notes': 'trot forward: tırıs gitmek.'}, {'id': 230, 'text': 'Great as Spitz had been, Buck proved himself instantly superior in judgment and authority.', 'translation': 'Spitz her ne kadar büyük olsa da, Buck muhakeme ve otoritede anında ondan üstün olduğunu kanıtladı.', 'notes': 'instantly superior: anında üstün.'}, {'id': 231, 'text': 'He punished shirkers swiftly, restored iron discipline, and bound the team into a single machine.', 'translation': 'Kaytaranları anında cezalandırdı, demir gibi bir disiplin kurdu ve takımı tek bir makine gibi birbirine kenetledi.', 'notes': 'iron discipline: demir disiplin.'}, {'id': 232, 'text': 'The team pulled as it had never pulled before, flying across the frozen expanses like the wind.', 'translation': 'Kızak takımı daha önce hiç çekmediği gibi çekti; donmuş arazilerde rüzgar gibi uçtu.', 'notes': 'flying like the wind: rüzgar gibi uçarak.'}, {'id': 233, 'text': 'They covered thirty, forty, and fifty miles a day, breaking all records on the Yukon trail.', 'translation': 'Günde otuz, kırk, elli mil yol katettiler; Yukon patikasındaki bütün rekorları altüst ettiler.', 'notes': 'breaking all records: tüm rekorları kırarak.'}, {'id': 234, 'text': 'They dashed into Dawson City in record time, greeted by cheering throngs of miners and officials.', 'translation': "Madencilerin ve yetkililerin alkışlayan kalabalıkları tarafından karşılanarak rekor sürede Dawson Şehri'ne girdiler.", 'notes': 'cheering throngs: tezahürat yapan kalabalıklar.'}, {'id': 235, 'text': 'For two days Buck was the hero of the town, celebrated for his strength and indomitable courage.', 'translation': 'Buck iki gün boyunca gücü ve boyun eğmez cesaretiyle övülen kasabanın kahramanı oldu.', 'notes': 'indomitable courage: boyun eğmez cesaret.'}, {'id': 236, 'text': 'Then came official orders from the government: Francois and Perrault were reassigned to other duties.', 'translation': 'Derken hükümetten resmi emirler geldi: Francois ve Perrault başka görevlere tayin edildiler.', 'notes': 'reassigned: yeniden tayin edildi.'}, {'id': 237, 'text': "Francois wept openly as he threw his arms around Buck's great furry neck.", 'translation': "Francois kollarını Buck'ın o kocaman tüylü boynuna dolarken hüngür hüngür ağladı.", 'notes': 'wept openly: açıkça ağladı.'}, {'id': 238, 'text': '"Au revoir, Buck!" he sobbed. "You are the best damn dog in all Canada!"', 'translation': '"Elveda Buck!" diye hıçkırdı. "Tüm Kanada\'daki en harika köpeksin sen!"', 'notes': 'au revoir: elveda (Fransızca).'}, {'id': 239, 'text': 'And that was the last Buck saw of the two kind-hearted couriers who had guided his northern education.', 'translation': "Ve bu, kuzeydeki eğitimine rehberlik eden o iki iyi yürekli ulağı Buck'ın son görüşü oldu.", 'notes': 'last saw: son gördüğü.'}, {'id': 240, 'text': 'A new master took the whip, and a heavier, more grueling journey was about to begin.', 'translation': 'Kamçıyı yeni bir efendi devraldı ve daha ağır, çok daha çetin bir yolculuk başlamak üzereydi.', 'notes': 'grueling journey: yıpratıcı yolculuk.'}]}, {'page_no': 13, 'title': "The Scotch Half-Breed and Dave's Dignity", 'tr_title': "İskoç Melezi, Ağır Posta Yükü ve Dave'in Onurlu Ölümü", 'vocab_focus': [('drudgery', 'ağır angarya, bezdirici iş'), ('monotony', 'monotonluk, tekdüzelik'), ('exhaustion', 'tükenme, bitkinlik'), ('agony', 'büyük acı'), ('unyielding', 'boyun eğmez, inatçı'), ('convoy', 'konvoy, kafile'), ('revolver', 'altıpatlar tabanca'), ('sorrow', 'keder, elem')], 'sentences': [{'id': 241, 'text': 'A Scotch half-breed took charge of the team to haul the heavy government mail.', 'translation': 'Ağır hükümet postasını çekmek üzere takımın idaresini bir İskoç melezi devraldı.', 'notes': 'took charge: idareyi devraldı.'}, {'id': 242, 'text': 'It was heavy work, the mail sacks weighing hundreds of pounds on the long trail back to Skagway.', 'translation': "Ağır bir işti bu; Skagway'e dönüş yolundaki o uzun patikada posta çuvalları yüzlerce pound çekiyordu.", 'notes': 'weighing hundreds: yüzlerce pound çeken.'}, {'id': 243, 'text': 'There was no glory now; only the monotonous, soul-crushing drudgery of daily hauling.', 'translation': 'Artık hiçbir zafer pırıltısı yoktu; sadece her gün araba çekmenin o tekdüze, ruhu ezen angaryası vardı.', 'notes': 'soul-crushing drudgery: ruhu ezen angarya.'}, {'id': 244, 'text': 'They carried letters to the lonely men who toiled for gold in the frozen creeks of the Klondike.', 'translation': "Klondike'ın donmuş derelerinde altın aramak için kan ter döken o yalnız adamlara mektuplar taşıyorlardı.", 'notes': 'toiled for gold: altın için çabalayan.'}, {'id': 245, 'text': 'Thirty days of constant toil wore down the muscles and broke the stamina of the dogs.', 'translation': 'Otuz günlük aralıksız çaba kasları yıprattı ve köpeklerin dayanma gücünü tüketti.', 'notes': 'wore down: yıprattı.'}, {'id': 246, 'text': 'Buck lost twenty pounds, but his iron constitution kept him pulling tirelessly in the lead.', 'translation': 'Buck yirmi pound kaybetti, fakat demir gibi bünyesi onu önde yorulmaksızın çeker vaziyette tuttu.', 'notes': 'iron constitution: demir gibi bünye.'}, {'id': 247, 'text': 'Something was terribly wrong with Dave, the gloomy wheeler who had served so faithfully.', 'translation': "Bunca zaman öyle sadakatle hizmet etmiş o kasvetli tekerlek köpeği Dave'de fena halde bir gariplik vardı.", 'notes': 'terribly wrong: fena halde yanlış.'}, {'id': 248, 'text': 'He became sullen and irritable, groaning softly whenever the heavy sled was jerked into motion.', 'translation': 'Ağır kızak her sarsılarak hareket ettiğinde alçak sesle inleyerek hırçın ve sinirli bir hale geldi.', 'notes': 'sullen and irritable: asık suratlı ve asabi.'}, {'id': 249, 'text': 'The drivers examined him repeatedly, but could find no broken bones or visible wounds.', 'translation': 'Sürücüler onu defalarca muayene ettiler, fakat ne kırık bir kemik ne de görünür bir yara bulabildiler.', 'notes': 'examined repeatedly: defalarca muayene etti.'}, {'id': 250, 'text': 'Something internal was broken; he was dying inside of some incurable agony.', 'translation': 'İçinde bir şeyler kopmuştu; çaresiz bir ızdırabın pençesinde içten içe can veriyordu.', 'notes': 'incurable agony: çaresiz acı.'}, {'id': 251, 'text': 'One morning he was so weak he could not rise to his feet when the camp was struck.', 'translation': 'Bir sabah kamp toplanırken öylesine bitkindi ki ayağa bile kalkamadı.', 'notes': 'when camp was struck: kamp toplanırken.'}, {'id': 252, 'text': "The driver harnessed Sol-leks in Dave's place, leaving the dying dog by the fire.", 'translation': "Sürücü, can çekişen köpeği ateşin başında bırakarak Dave'in yerine Sol-leks'i koştu.", 'notes': 'harnessed in place: yerine koştu.'}, {'id': 253, 'text': 'Dave could not bear that another dog should do the work that was his lifelong pride.', 'translation': 'Hayatı boyunca duyduğu en büyük gurur olan kendi işini bir başka köpeğin yapmasına Dave katlanamadı.', 'notes': 'could not bear: dayanamadı.'}, {'id': 254, 'text': "He crawled through the snow, biting at Sol-leks's traces, pleading with his eyes to be returned to his place.", 'translation': "Karlarda sürünerek gitti; Sol-leks'in iplerini dişledi; yerine geri dönmek için gözleriyle yalvardı.", 'notes': 'pleading with eyes: gözleriyle yalvararak.'}, {'id': 255, 'text': 'The drivers understood; they could not deny a faithful dog the right to die in his traces.', 'translation': 'Sürücüler anladılar; sadık bir köpeğe kendi koşum iplerinde ölme hakkını çok göremezlerdi.', 'notes': 'could not deny: inkar edemezlerdi / çok göremezlerdi.'}, {'id': 256, 'text': 'They harnessed Dave once more, and he pulled with supreme, tragic pride all that day.', 'translation': "Dave'i bir kez daha kızağa koştular ve o gün boyunca muazzam, trajik bir gururla çekti.", 'notes': 'tragic pride: trajik gurur.'}, {'id': 257, 'text': 'The next morning he could only crawl on his belly, unable to stand, whimpering softly.', 'translation': 'Ertesi sabah ayağa kalkamaz halde, kısık sesle inleyerek sadece karnı üzerinde sürünebiliyordu.', 'notes': 'crawl on his belly: karnı üstünde sürünmek.'}, {'id': 258, 'text': 'The sled moved off into the woods, leaving Dave lying alone in the snow.', 'translation': "Kızak Dave'i karların içinde yapayalnız bırakarak ormanın içine doğru ilerledi.", 'notes': 'moved off: uzaklaştı.'}, {'id': 259, 'text': 'The driver halted the team, walked back with his revolver into the trees, and a shot echoed through the silence.', 'translation': 'Sürücü takımı durdurdu, elinde tabancasıyla ağaçların arasına geri yürüdü ve sessizliğin içinde bir el silah sesi yankılandı.', 'notes': 'shot echoed: kurşun sesi yankılandı.'}, {'id': 260, 'text': 'The driver returned, cracked his whip, and the dogs surged forward, knowing that Dave had found peace.', 'translation': "Sürücü geri döndü, kamçısını şaklattı ve Dave'in huzura kavuştuğunu bilen köpekler ileriye atıldı.", 'notes': 'had found peace: huzura ermişti.'}]}, {'page_no': 14, 'title': 'The Incompetent Trio: Hal, Charles, and Mercedes', 'tr_title': 'Acemi Güneyliler: Hal, Charles ve Mercedes', 'vocab_focus': [('incompetent', 'beceriksiz, acemi'), ('overloaded', 'aşırı yüklü'), ('quarrel', 'tartışmak, kavga etmek'), ('whim', 'kapris, şımarıklık'), ('inexperienced', 'deneyimsiz'), ('exhausted', 'bitkin, tükenmiş'), ('clumsy', 'hantal, sakar'), ('ridiculous', 'gülünç, saçma')], 'sentences': [{'id': 261, 'text': 'Thirty days later, the mail train arrived in Skagway with dogs battered and muscles exhausted.', 'translation': "Otuz gün sonra posta kızağı köpekleri hırpalanmış ve kasları tükenmiş halde Skagway'e vardı.", 'notes': 'battered: hırpalanmış, yıpranmış.'}, {'id': 262, 'text': 'In less than five months they had covered twenty-five hundred miles of frozen Arctic wilderness.', 'translation': 'Beş aydan kısa bir sürede donmuş Arktik yabanında iki bin beş yüz mil yol katetmişlerdi.', 'notes': 'twenty-five hundred: iki bin beş yüz.'}, {'id': 263, 'text': 'They were dead beat, their legs shaking, needing at least two weeks of complete rest.', 'translation': 'Bacakları tir tir titreyerek pestilleri çıkmıştı; en az iki haftalık tam bir dinlenmeye muhtaçtılar.', 'notes': 'dead beat: pestili çıkmış, tükenmiş.'}, {'id': 264, 'text': 'Instead, three days later, official orders commanded that the worn-out dogs be sold at auction.', 'translation': 'Bunun yerine üç gün sonra gelen resmi emirler, bu tükenmiş köpeklerin açık artırmada satılmasını buyurdu.', 'notes': 'sold at auction: açık artırmada satılmak.'}, {'id': 265, 'text': 'Two men from the States, Hal and Charles, bought them for a song.', 'translation': "Birleşik Devletler'den gelen iki adam, Hal ve Charles, onları kelepir fiyatına satın aldı.", 'notes': 'for a song: yok pahasına, kelepir fiyata.'}, {'id': 266, 'text': 'Charles was a middle-aged, weak-eyed man, while Hal was a callow youth of nineteen carrying a big revolver and knife.', 'translation': 'Charles gözleri zayıf, orta yaşlı bir adamdı; Hal ise belinde koca bir tabanca ve bıçak taşıyan on dokuz yaşında toy bir gençti.', 'notes': 'callow youth: toy/acemi genç.'}, {'id': 267, 'text': "With them was Mercedes, Charles's wife and Hal's sister, a spoiled, complaining lady.", 'translation': "Yanlarında Charles'ın karısı ve Hal'ın kız kardeşi olan şımarık, durmadan söylenen bir hanımefendi, Mercedes vardı.", 'notes': 'spoiled: şımarık.'}, {'id': 268, 'text': 'They were completely inexperienced in northern travel and refused to take advice from experienced miners.', 'translation': 'Kuzey yolculuğunda tamamen tecrübesizdiler ve kıdemli madencilerin tavsiyelerini dinlemeyi reddediyorlardı.', 'notes': 'refused to take advice: tavsiye almayı reddetti.'}, {'id': 269, 'text': 'Their camp was in utter disorder, tents unrolled, dishes unwashed, and baggage heaped in chaotic piles.', 'translation': 'Kampları mutlak bir düzensizlik içindeydi; çadırlar gelişigüzel açılmış, kaplar yıkanmamış, bagajlar karmakarışık yığılmıştı.', 'notes': 'utter disorder: mutlak düzensizlik.'}, {'id': 270, 'text': 'They piled the sled with useless luxuries: tin boxes, huge trunks, clothes hampers, and delicate canned goods.', 'translation': 'Kızağı lüzumsuz lükslerle doldurdular: teneke kutular, koca sandıklar, çamaşır sepetleri ve narin konserve kutuları.', 'notes': 'delicate canned goods: narin konserveler.'}, {'id': 271, 'text': 'The load rose twice as high as any experienced Arctic traveller would dare to pack.', 'translation': 'Yük, tecrübeli hiçbir Arktik yolcusunun cesaret edemeyeceği kadar, normalin iki katı yüksekliğe ulaştı.', 'notes': 'twice as high: iki kat yüksek.'}, {'id': 272, 'text': 'When the dogs failed to move the mountainous weight, Hal beat them mercilessly with a heavy club.', 'translation': 'Köpekler o dağ gibi ağırlığı kıpırdatmayı başaramayınca Hal ağır bir sopayla onlara acımasızca vurdu.', 'notes': 'mountainous weight: dağ gibi ağırlık.'}, {'id': 273, 'text': '"The runners are frozen fast to the snow, you fool!" an onlooker shouted in disgust.', 'translation': '"Kızak ayakları kara donup yapışmış be ahmak!" diye seyircilerden biri tiksintiyle bağırdı.', 'notes': 'frozen fast: donup yapışmış.'}, {'id': 274, 'text': 'The spectators broke the runners loose, and the dogs surged forward, straining every fiber of their muscles.', 'translation': 'İzleyiciler kızak ayaklarını dondan kurtardılar ve köpekler kaslarının her bir lifini zorlayarak ileriye atıldılar.', 'notes': 'straining every fiber: her lifi zorlayarak.'}, {'id': 275, 'text': 'At the first sharp turn in the road, the top-heavy sled toppled over into the deep snow.', 'translation': 'Yoldaki ilk keskin virajda üstü aşırı yüklü kızak derin karların içine devriliverdi.', 'notes': 'top-heavy: tepesi aşırı ağır.'}, {'id': 276, 'text': 'Baggage, trunks, and clothing scattered everywhere across the street amidst the laughter of the townspeople.', 'translation': 'Kasabalıların kahkahaları arasında bavullar, sandıklar ve giysiler caddenin dört bir yanına saçıldı.', 'notes': 'scattered everywhere: her yere saçıldı.'}, {'id': 277, 'text': 'Instead of lightening the load, Hal bought six additional outside dogs to haul the tremendous weight.', 'translation': 'Yükü hafifletmek yerine Hal, o devasa ağırlığı çeksin diye dışarıdan altı ek köpek daha satın aldı.', 'notes': 'additional dogs: ek köpekler.'}, {'id': 278, 'text': 'Now there were fourteen dogs, but the sled could not carry enough food for such a large team.', 'translation': 'Artık on dört köpek vardı, fakat kızak böylesine kalabalık bir takım için yeterli yiyeceği taşıyamazdı.', 'notes': 'could not carry: taşıyamazdı.'}, {'id': 279, 'text': 'Buck had never seen such incompetence; he knew with canine instinct that disaster lay ahead.', 'translation': 'Buck ömründe böylesi bir beceriksizlik görmemişti; köpek içgüdüsüyle ileride bir felaketin beklediğini biliyordu.', 'notes': 'canine instinct: köpek içgüdüsü.'}, {'id': 280, 'text': 'They set off across the rotting spring ice toward Dawson with doom written upon their banner.', 'translation': "Bayraklarında adeta felaket yazılı olarak, eriyip çürüyen bahar buzları üzerinden Dawson'a doğru yola çıktılar.", 'notes': 'rotting spring ice: çürüyen/eriyen bahar buzu.'}]}, {'page_no': 15, 'title': 'The Starvation Trail to White River', 'tr_title': "Açlık Yolu ve Beyaz Nehir'e Doğru Ölümcül Yürüyüş", 'vocab_focus': [('starvation', 'açlık, açlıktan ölme'), ('shortage', 'kıtlık, noksanlık'), ('rations', 'tayın, günlük porsiyon'), ('rotting', 'çürüyen, eriyen'), ('skeleton', 'bir deri bir kemik'), ('collapse', 'yere yığılmak, çökmek'), ('spring', 'ilkbahar'), ('perish', 'can vermek, ölmek')], 'sentences': [{'id': 281, 'text': 'It was a heartbreaking journey through the softening snow under the warm spring sun.', 'translation': 'Ilık bahar güneşi altında yumuşayan karların arasından geçen yürek parçalayıcı bir yolculuktu bu.', 'notes': 'heartbreaking: yürek parçalayıcı.'}, {'id': 282, 'text': 'The trio quarrelled incessantly, blaming each other for their own blunders and delays.', 'translation': 'Bu üçlü kendi gafletleri ve gecikmeleri yüzünden birbirini suçlayarak aralıksız kavga ediyordu.', 'notes': 'quarrelled incessantly: durmaksızın kavga etti.'}, {'id': 283, 'text': 'Mercedes wept, threw tantrums, and insisted on riding upon the overloaded sled herself.', 'translation': 'Mercedes ağlıyor, kapris krizlerine giriyor ve o aşırı yüklü kızağın tepesinde oturmakta ısrar ediyordu.', 'notes': 'threw tantrums: kapris nöbetlerine girdi.'}, {'id': 284, 'text': 'She added one hundred and twenty pounds of useless weight to the burdens of the starving animals.', 'translation': 'Açlıktan kıvranan hayvanların yüküne yüz yirmi poundluk gereksiz bir ağırlık daha ekliyordu.', 'notes': 'useless weight: yararsız ağırlık.'}, {'id': 285, 'text': 'Halfway to White River, the dog food was completely exhausted due to overfeeding in the first days.', 'translation': 'İlk günlerdeki aşırı besleme yüzünden Beyaz Nehir yolunun yarısında köpek maması tamamen tükendi.', 'notes': 'completely exhausted: tamamen bitti/tükendi.'}, {'id': 286, 'text': 'Hal cut the rations in half, then into quarters, and finally had only rotten horsehide to offer.', 'translation': 'Hal porsiyonları yarıya indirdi, sonra çeyreğe düşürdü ve sonunda verecek sadece çürük at derisi kaldı.', 'notes': 'rotten horsehide: çürük at derisi.'}, {'id': 287, 'text': 'The outside dogs, unaccustomed to harsh trail life, perished one by one of sheer starvation.', 'translation': 'Zorlu patika hayatına alışkın olmayan dışarıdan alınan köpekler katıksız açlıktan teker teker can verdi.', 'notes': 'perished one by one: teker teker öldü.'}, {'id': 288, 'text': 'Dub injured his shoulder and was shot; Dolly went mad with rabies and had to be killed.', 'translation': 'Dub omzundan sakatlandı ve vuruldu; Dolly kudurarak delirdi ve öldürülmek zorunda kalındı.', 'notes': 'went mad: delirdi.'}, {'id': 289, 'text': 'Joe and Billee could pull no more; one morning they could not rise, and their places were empty.', 'translation': 'Joe ve Billee artık çekemez hale geldi; bir sabah kalkamadılar ve yerleri boş kaldı.', 'notes': 'pull no more: artık çekememek.'}, {'id': 290, 'text': 'Only five dogs remained: Sol-leks, Teek, Koona, Pike, and Buck, all walking skeletons.', 'translation': 'Geriye sadece beş köpek kaldı: Sol-leks, Teek, Koona, Pike ve Buck; hepsi de ayaklı birer iskelet gibiydi.', 'notes': 'walking skeletons: ayaklı iskeletler.'}, {'id': 291, 'text': 'Buck had lost his magnificent bulk; his ribs and hollow flanks showed clearly through his matted coat.', 'translation': 'Buck o görkemli cüssesini kaybetmişti; kaburgaları ve çökmüş böğrü keçeleşmiş kürkünün altından açıkça görünüyordu.', 'notes': 'hollow flanks: çökmüş böğürler.'}, {'id': 292, 'text': 'He moved in a daze of pain and weakness, numbness creeping into his tired soul.', 'translation': 'Yorgun ruhuna bir uyuşukluk sızarken acı ve güçsüzlük sersemliği içinde adım atıyordu.', 'notes': 'in a daze: sersemlik içinde.'}, {'id': 293, 'text': 'The spring thaw was advancing with terrifying speed all across the Yukon basin.', 'translation': 'Baharın buz erimesi tüm Yukon havzası boyunca korkutucu bir hızla ilerliyordu.', 'notes': 'spring thaw: bahar buz erimesi.'}, {'id': 294, 'text': 'The sun shone brightly, melting the snow into slush, and running water sang under the rotting river ice.', 'translation': 'Güneş pırıl pırıl parlıyor, karları sulu çamura çeviriyor ve çürüyen nehir buzunun altında akan sular şırıldıyordu.', 'notes': 'rotting river ice: çürüyen nehir buzu.'}, {'id': 295, 'text': 'Great air-holes opened in the ice every mile, and the bottom of the river showed through green chasms.', 'translation': 'Buzda her mil başında büyük hava delikleri açılıyor ve nehrin dibi yeşil yarıkların arasından görünüyordu.', 'notes': 'green chasms: yeşil yarıklar/uçurumlar.'}, {'id': 296, 'text': 'Every step upon the trail was fraught with deadly peril of sinking into the freezing flood.', 'translation': 'Patikadaki her adım o dondurucu akıntıya gömülmenin ölümcül tehlikesiyle doluydu.', 'notes': 'fraught with: ile dolu.'}, {'id': 297, 'text': 'Pike fell down in his traces and could not get up; Hal killed him with the club and threw him aside.', 'translation': 'Pike koşumlarında yere yığıldı ve kalkamadı; Hal sopayla onu öldürüp kenara fırlattı.', 'notes': 'threw aside: kenara attı.'}, {'id': 298, 'text': 'Only Buck, Sol-leks, and the two others staggered on, dragging the heavy sled through the mud.', 'translation': 'Yalnızca Buck, Sol-leks ve diğer ikisi sendeleyerek yürüdü; ağır kızağı çamurların içinden çekerek.', 'notes': 'staggered on: sendeleyerek devam etti.'}, {'id': 299, 'text': 'At last, on a brilliant morning, they crawled into the camp of John Thornton at the mouth of White River.', 'translation': "Nihayet pırıl pırıl bir sabahta Beyaz Nehir'in ağzında John Thornton'ın kampına sürünerek girdiler.", 'notes': 'crawled into: sürünerek girdi.'}, {'id': 300, 'text': 'Buck collapsed onto the ground, his strength utterly gone, unable to take another step.', 'translation': 'Dermanı tamamen tükenmiş, tek bir adım daha atamaz halde Buck yere yığıldı.', 'notes': 'strength utterly gone: dermanı büsbütün bitmiş.'}]}, {'page_no': 16, 'title': "John Thornton's Intervention", 'tr_title': "John Thornton'ın Müdahalesi ve Buck'ın Kurtarılışı", 'vocab_focus': [('intervention', 'araya girme, müdahale'), ('whittle', 'çakıyla tahta yontmak'), ('brutality', 'gaddarlık, vahşet'), ('threaten', 'tehdit etmek'), ('revolver', 'tabanca'), ('knife', 'av bıçağı'), ('protect', 'korumak'), ('deliverance', 'kurtuluş, esaretten azat')], 'sentences': [{'id': 301, 'text': 'John Thornton was whittling an axe-handle from a piece of birchwood as the wretched outfit halted.', 'translation': 'O sefil kafile durduğunda John Thornton huş ağacından bir balta sapı yontuyordu.', 'notes': 'whittling: çakıyla yontarak.'}, {'id': 302, 'text': 'He looked at the dying dogs and the ragged humans with silent, contemptuous disgust.', 'translation': 'Can çekişen köpeklere ve üstü başı dökülen insanlara sessiz, küçümseyen bir tiksintiyle baktı.', 'notes': 'contemptuous disgust: küçümser tiksinti.'}, {'id': 303, 'text': '"Is it safe to cross the river ice to Dawson?" Hal asked, panting from exhaustion.', 'translation': '"Nehir buzunun üzerinden Dawson\'a geçmek güvenli mi?" diye sordu Hal, yorgunluktan soluk soluğa.', 'notes': 'safe to cross: karşıya geçmesi güvenli.'}, {'id': 304, 'text': '"They told you true in town," Thornton answered tersely. "The bottom is dropping out of the trail."', 'translation': '"Kasabada size doğruyu söylemişler," dedi Thornton kısaca. "Patikanın tabanı çöktü çökecek."', 'notes': 'tersely: kısa ve öz, tersler gibi.'}, {'id': 305, 'text': '"Only a fool would venture upon that rotten ice today; it will break at any second."', 'translation': '"Bugün o çürük buzun üzerine ancak bir ahmak adım atar; her saniye kırılabilir."', 'notes': 'venture upon: üzerine adım atmaya cüret etmek.'}, {'id': 306, 'text': '"We\'ve been told that before," sneered Hal, "and we got here anyway. Mush, you devils!"', 'translation': '"Bunu bize daha önce de söylediler," diye alay etti Hal, "ve yine de buraya vardık. Deh, sizi iblisler!"', 'notes': 'sneered: alaycı konuştu.'}, {'id': 307, 'text': 'He lashed out with his whip, striking Sol-leks, Teek, and Koona, forcing them to their feet.', 'translation': "Kamçısını savurdu; Sol-leks, Teek ve Koona'ya vurarak onları güçlükle ayağa kaldırdı.", 'notes': 'lashed out: kamçıyla savurdu.'}, {'id': 308, 'text': 'Buck did not move; a sense of impending doom told him that the ice was fatal.', 'translation': 'Buck kımıldamadı; yaklaşan felaketin önsezisi ona o buzun ölümcül olduğunu söylüyordu.', 'notes': 'impending doom: yaklaşan felaket.'}, {'id': 309, 'text': "Hal dropped the whip and took up the heavy club, raining brutal blows upon Buck's emaciated body.", 'translation': "Hal kamçıyı bıraktı ve ağır sopayı eline alarak Buck'ın bir deri bir kemik kalmış gövdesine acımasız darbeler yağdırdı.", 'notes': 'raining brutal blows: gaddar darbeler yağdırarak.'}, {'id': 310, 'text': 'Buck took the blows without a whimper, refusing to stand, welcoming death rather than that icy river.', 'translation': 'Buck o buzlu nehre gitmektense ölümü yeğleyerek ayağa kalkmayı reddetti ve darbeleri hiç inlemeden karşıladı.', 'notes': 'welcoming death: ölümü kucaklayarak.'}, {'id': 311, 'text': 'Thornton sprang to his feet, his eyes blazing with righteous fury.', 'translation': 'Thornton gözleri haklı bir öfkeyle parıldayarak yerinden fırladı.', 'notes': 'righteous fury: haklı gazap.'}, {'id': 312, 'text': '"If you strike that dog once more, I\'ll kill you!" he shouted, stepping between Hal and Buck.', 'translation': '"O köpeğe bir kez daha vurursan seni öldürürüm!" diye bağırdı, Hal ile Buck\'ın arasına girerek.', 'notes': 'stepping between: aralarına girerek.'}, {'id': 313, 'text': '"It\'s my dog!" Hal cried, drawing his hunting knife. "Get out of my way or I\'ll fix you!"', 'translation': '"O benim köpeğim!" diye haykırdı Hal av bıçağını çekerek. "Yolumdan çekil yoksa seni delik deşik ederim!"', 'notes': 'fix you: hesabını görmek (tehdit).'}, {'id': 314, 'text': "Thornton struck Hal's knuckles with the axe-handle, knocking the blade spinning into the dirt.", 'translation': "Thornton balta sapıyla Hal'ın parmak eklemlerine vurdu; bıçağı havada döndürerek toprağa düşürdü.", 'notes': 'knuckles: parmak eklemleri.'}, {'id': 315, 'text': 'He then struck Hal across the chest, sending him sprawling backwards onto the sled.', 'translation': "Ardından Hal'ın göğsüne vurarak onu sırtüstü kızağın üzerine savurdu.", 'notes': 'sprawling backwards: sırtüstü savrularak.'}, {'id': 316, 'text': 'Thornton knelt down by Buck and cut his traces with his own hunting knife, freeing him from the harness.', 'translation': "Thornton Buck'ın yanına diz çöktü ve kendi av bıçağıyla çekme iplerini keserek onu koşumdan kurtardı.", 'notes': 'freeing from harness: koşumdan azat ederek.'}, {'id': 317, 'text': "Hal stood up, cursing violently, but Thornton's determined look warned him not to press the issue.", 'translation': "Hal avazı çıktığı kadar küfrederek ayağa kalktı, fakat Thornton'ın kararlı bakışı meseleyi uzatmaması için onu uyardı.", 'notes': 'press the issue: meseleyi üstelemek.'}, {'id': 318, 'text': 'The young man turned away in disgust, took the sled lines, and shouted to the four remaining dogs.', 'translation': 'Genç adam tiksintiyle döndü, kızak dizginlerini eline aldı ve geriye kalan dört köpeğe bağırdı.', 'notes': 'sled lines: kızak ipleri/dizginleri.'}, {'id': 319, 'text': 'Mercedes, Charles, and Hal set off across the slushy snow, heading out onto the fragile river ice.', 'translation': 'Mercedes, Charles ve Hal sulu karların üzerinden yola çıktılar; o kırılgan nehir buzuna doğru ilerleyerek.', 'notes': 'heading out onto: ...e doğru yol alarak.'}, {'id': 320, 'text': "Buck watched them go, lying beside Thornton, who gently rested a warm hand upon the great dog's battered head.", 'translation': "Büyük köpeğin hırpalanmış başına sıcak elini şefkatle koyan Thornton'ın yanında yatan Buck onların gidişini izledi.", 'notes': 'gently rested: şefkatle koydu.'}]}, {'page_no': 17, 'title': 'The Ice Breaks and the Fools Perish', 'tr_title': 'Buzun Çöküşü ve Ahmakların Sulara Gömülmesi', 'vocab_focus': [('chasm', 'yarık, derin uçurum'), ('submerge', 'tamamen batmak'), ('swallow', 'yutmak'), ('abyss', 'derin uçurum, dipsiz kuyu'), ('reckless', 'pervasız, tedbirsiz'), ('doom', 'kıyamet, felaket'), ('witness', 'tanık olmak, şahit'), ('deliverance', 'kurtuluş')], 'sentences': [{'id': 321, 'text': 'Buck and John Thornton watched the sled crawl out toward the center of the White River.', 'translation': "Buck ve John Thornton, kızağın Beyaz Nehir'in ortasına doğru sürünerek ilerleyişini izlediler.", 'notes': 'crawl out toward: doğru sürünerek ilerlemek.'}, {'id': 322, 'text': 'The ice sagged and groaned beneath the heavy weight of the cargo and the passengers.', 'translation': 'Yükün ve yolcuların ağır yükü altında buz çöktü ve inledi.', 'notes': 'sagged and groaned: çöktü ve inledi.'}, {'id': 323, 'text': 'Suddenly, they saw the rear end of the sled drop down as if into a rut, and the pole shot up into the air.', 'translation': 'Birdenbire kızağın arka kısmının sanki bir çukura düşer gibi çöktüğünü ve ön sırığın havaya fırladığını gördüler.', 'notes': 'shot up: havaya fırladı.'}, {'id': 324, 'text': 'Mercedes gave a piercing shriek of terror that echoed across the frozen valley.', 'translation': 'Mercedes, donmuş vadide yankılanan kulak tırmalayıcı bir dehşet çığlığı attı.', 'notes': 'piercing shriek: tiz çığlık.'}, {'id': 325, 'text': 'Charles turned to run back, but a yawning chasm opened directly beneath his boots.', 'translation': 'Charles geri kaçmak için döndü, fakat doğrudan çizmelerinin altında açgözlü bir yarık açıldı.', 'notes': 'yawning chasm: ağzı açık derin yarık.'}, {'id': 326, 'text': 'A whole section of ice gave way with a thunderous roar, plunging men, dogs, and sled into the dark current.', 'translation': 'Buzun koca bir kesiti gök gürültüsünü andıran bir kükremeyle çöktü; insanları, köpekleri ve kızağı kara akıntının içine yuvarladı.', 'notes': 'plunging into: içine yuvarlayarak/dalarak.'}, {'id': 327, 'text': 'For a split second, hands flailed wildly and struggling heads appeared in the churning, icy foam.', 'translation': 'Saniyenin bir kesri boyunca eller çılgınca çırpındı ve köpüren buzlu dalgaların arasında mücadele eden kafalar göründü.', 'notes': 'flailed wildly: çılgınca çırpındı.'}, {'id': 328, 'text': 'Then the powerful river current swept them beneath the remaining ice sheets, and they vanished forever.', 'translation': 'Ardından nehrin o güçlü akıntısı onları geride kalan buz tabakalarının altına sürükledi ve sonsuza dek yok oldular.', 'notes': 'swept beneath: altına süpürdü.'}, {'id': 329, 'text': 'A wide, dark pool of open water was all that marked where the sled and its travellers had been.', 'translation': 'Kızak ve yolcularının bir zamanlar bulunduğu yeri belirten tek şey, açılan geniş, kara bir su birikintisinden ibaretti.', 'notes': 'all that marked: belirten tek şey.'}, {'id': 330, 'text': 'John Thornton and Buck looked at each other in solemn, speechless awe.', 'translation': 'John Thornton ve Buck vakur, kelimelere sığmayan bir huşu içinde birbirlerine baktılar.', 'notes': 'speechless awe: dilsiz bir huşu/dehşet.'}, {'id': 331, 'text': '"You poor devil," said John Thornton, his voice trembling as he touched Buck\'s head.', 'translation': '"Zavallı dostum benim," dedi John Thornton; Buck\'ın başına dokunurken sesi titriyordu.', 'notes': 'poor devil: zavallıcık (şefkatli hitap).'}, {'id': 332, 'text': "Buck licked Thornton's hand with rough affection, sensing that here was a master who ruled by love, not by the club.", 'translation': "Buck kaba bir sevgiyle Thornton'ın elini yaladı; burada sopayla değil sevgiyle hükmeden bir efendi olduğunu sezerek.", 'notes': 'ruled by love: sevgiyle hükmetti.'}, {'id': 333, 'text': 'Had Thornton not intervened, Buck would now be tumbling dead beneath the dark ice of the Yukon.', 'translation': "Thornton araya girmemiş olsaydı Buck şu an Yukon'un kara buzlarının altında cansız yuvarlanıyor olacaktı.", 'notes': 'had Thornton not intervened: araya girmemiş olsaydı.'}, {'id': 334, 'text': 'A profound bond of loyalty was forged between the man and the dog in that fateful moment.', 'translation': 'O kader anında adamla köpek arasında derin bir sadakat bağı örüldü.', 'notes': 'was forged: dövüldü, inşa edildi.'}, {'id': 335, 'text': 'Thornton had been left behind by his partners while recovering from frozen feet during the winter.', 'translation': 'Thornton, kışın donan ayaklarını iyileştirirken ortakları tarafından bu kampta geride bırakılmıştı.', 'notes': 'recovering from: ...den toparlanırken.'}, {'id': 336, 'text': 'He lived in a comfortable camp with two other dogs: Skeet, a motherly Irish setter, and Nig, a huge black hound.', 'translation': 'İki köpekle birlikte rahat bir kampta yaşıyordu: anaç bir İrlanda setteri olan Skeet ve devasa siyah bir av köpeği olan Nig.', 'notes': 'motherly: anaç, şefkatli.'}, {'id': 337, 'text': "Skeet washed Buck's bleeding wounds daily with her soft tongue, nursing him like a mother dog.", 'translation': "Skeet, Buck'ın kanayan yaralarını yumuşak diliyle her gün yıkadı; ona bir anne gibi baktı.", 'notes': 'nursing like a mother: anne gibi bakarak.'}, {'id': 338, 'text': 'Nig, equally friendly, greeted him with joyful barks, showing no jealousy toward the newcomer.', 'translation': 'Aynı derecede dost canlısı olan Nig, yeni gelene en ufak bir kıskançlık göstermeden neşeli havlamalarla onu karşıladı.', 'notes': 'no jealousy: hiç kıskançlık yok.'}, {'id': 339, 'text': 'Through long lazy spring days, Buck lay in the warm sunshine, feeling his wasted muscles slowly rebuild.', 'translation': 'Uzun, rehavet dolu bahar günleri boyunca Buck ılık güneş ışığında yattı; eriyip tükenmiş kaslarının yavaş yavaş yeniden güçlendiğini hissederek.', 'notes': 'slowly rebuild: yavaşça yeniden yapılanmak.'}, {'id': 340, 'text': 'His strength returned, his coat regained its glossy thickness, and a new life began.', 'translation': 'Gücü yerine geldi, kürkü o parlak gürlüğünü yeniden kazandı ve onun için yepyeni bir hayat başladı.', 'notes': 'glossy thickness: parlak gürlük/kalınlık.'}]}, {'page_no': 18, 'title': 'For the Love of a Man', 'tr_title': 'Bir İnsana Duyulan Sonsuz ve Koşulsuz Sevgi', 'vocab_focus': [('adoration', 'taparcasına sevgi, hayranlık'), ('feverish', 'hummalı, ateşli'), ('caress', 'okşama, şefkat gösterme'), ('devotion', 'bağlılık, sadakat'), ('partner', 'ortak, yoldaş'), ('wilderness', 'yaban hayatı, vahşi doğa'), ('ecstasy', 'büyük vecd, kendinden geçme'), ('primitive', 'ilkel, ilkçağa ait')], 'sentences': [{'id': 341, 'text': 'For the first time in his life, Buck experienced the burning passion of true love.', 'translation': 'Hayatında ilk kez Buck, gerçek sevginin o yakıcı tutkusunu tattı.', 'notes': 'burning passion: yakıcı tutku.'}, {'id': 342, 'text': 'With Judge Miller, it had been a dignified, aristocratic partnership of mutual respect.', 'translation': 'Yargıç Miller ile olan ilişkisi, karşılıklı saygıya dayalı vakur ve soylu bir ortaklıktı.', 'notes': 'mutual respect: karşılıklı saygı.'}, {'id': 343, 'text': 'With John Thornton, it was an all-consuming adoration that bordered on feverish ecstasy.', 'translation': 'John Thornton ile ise, hummalı bir kendinden geçişin sınırlarında dolaşan her şeyi içine alan bir tapınmaydı.', 'notes': 'all-consuming adoration: her şeyi yutan tapınma.'}, {'id': 344, 'text': 'This man had saved his life, which was something; but, further, he was the ideal master.', 'translation': 'Bu adam onun hayatını kurtarmıştı, ki bu büyük bir şeydi; fakat dahası, o ideal efendinin ta kendisiydi.', 'notes': 'ideal master: ideal efendi.'}, {'id': 345, 'text': 'Other men saw to the welfare of their dogs from a sense of duty and business interest.', 'translation': 'Diğer insanlar köpeklerinin bakımını sadece bir görev duygusu ve ticari çıkar gereği gözetirlerdi.', 'notes': 'sense of duty: görev bilinci.'}, {'id': 346, 'text': 'John Thornton saw to the welfare of his dogs as if they were his own flesh-and-blood children.', 'translation': 'John Thornton ise köpeklerinin esenliğini adeta kendi etten kemikten evlatlarıymış gibi gözetirdi.', 'notes': 'flesh-and-blood: etten ve kemikten.'}, {'id': 347, 'text': "He had a way of taking Buck's head roughly between his hands, resting his own head upon Buck's.", 'translation': "Buck'ın başını ellerinin arasına sevgiyle sertçe alıp kendi başını Buck'ınkine yaslama huyu vardı.", 'notes': 'resting his head: başını yaslayarak.'}, {'id': 348, 'text': "And calling him affectionate curse words that sounded in Buck's ears like the sweetest music.", 'translation': "Ve ona Buck'ın kulaklarında en tatlı müzik gibi tınlayan şefkatli küfürlerle hitap ederdi.", 'notes': 'affectionate curse words: sevgi dolu küfürler.'}, {'id': 349, 'text': 'Buck had a trick of expression that was akin to speech.', 'translation': "Buck'ın konuşmaya benzeyen kendine has bir ifade tarzı vardı.", 'notes': 'akin to: ...e benzer.'}, {'id': 350, 'text': "He would seize Thornton's hand in his mouth, closing his powerful jaws until the teeth pressed into the flesh.", 'translation': "Thornton'ın elini ağzının içine alır, güçlü çenelerini dişleri etine batana kadar sıkar ama asla incitmezdi.", 'notes': 'pressed into: içine bastırdı.'}, {'id': 351, 'text': "It was a mock bite, a silent declaration that he surrendered his life entirely into the man's keeping.", 'translation': 'Bu sahte bir ısırmaydı; canını tamamen bu adamın ellerine teslim ettiğine dair sessiz bir ilandı.', 'notes': 'mock bite: sahte ısırık.'}, {'id': 352, 'text': "For long hours he would lie at Thornton's feet, staring up into his face with worshipful adoration.", 'translation': "Uzun saatler boyunca Thornton'ın ayaklarının dibinde yatar; taparcasına bir sevgiyle yüzüne bakardı.", 'notes': 'worshipful adoration: taparcasına hayranlık.'}, {'id': 353, 'text': 'He could not bear to let Thornton out of his sight, fearing he might vanish like Perrault and Francois.', 'translation': "Tıpkı Perrault ve Francois gibi onun da yok olabileceğinden korkarak Thornton'ı gözünün önünden ayırmaya dayanamazdı.", 'notes': 'out of his sight: gözünün önünden.'}, {'id': 354, 'text': 'Yet along with this great love for the man, the call of the wild was growing stronger within him.', 'translation': 'Yine de adama duyduğu bu büyük sevgiyle birlikte, vahşi doğanın çağrısı da içinde giderek güçleniyordu.', 'notes': 'call of the wild: vahşi doğanın çağrısı.'}, {'id': 355, 'text': 'Deep in the forest sounded an ancient, mysterious cry, tempting him away from human fire and roof.', 'translation': 'Ormanın derinliklerinde, insan ateşinden ve damından onu uzağa çağıran kadim, gizemli bir çığlık yankılanıyordu.', 'notes': 'tempting away: aklını çelip uzaklaştıran.'}, {'id': 356, 'text': 'Often he would turn his head toward the shadowy timber, listening with prickled ears to the silent wilderness.', 'translation': 'Kulaklarını dikip o sessiz yaban hayatını dinleyerek başını sık sık gölgeli ormana doğru çevirirdi.', 'notes': 'prickled ears: dikilmiş kulaklar.'}, {'id': 357, 'text': 'He felt memories of ancestors he had never seen running through his blood and sinews.', 'translation': 'Daha önce hiç görmediği atalarının hatıralarının kanında ve kaslarında aktığını hissediyordu.', 'notes': 'blood and sinews: kan ve kaslar.'}, {'id': 358, 'text': 'He saw the ancient hairy men crouching by rough fires, watching the shadows of the primeval woods.', 'translation': 'İlkel ormanların gölgelerini izleyerek ilkel ateşlerin başında çömelmiş o kadim tüylü adamları hayalinde görürdü.', 'notes': 'primeval woods: ilkel ormanlar.'}, {'id': 359, 'text': 'The wild was calling him constantly, inviting him to return to the primitive heritage of the wolf.', 'translation': 'Vahşi doğa onu durmadan çağırıyor; kurdun o ilkel mirasına geri dönmesi için onu davet ediyordu.', 'notes': 'primitive heritage: ilkel miras.'}, {'id': 360, 'text': 'Only one chain held him back from the wild forest: the fierce, tender love he bore for John Thornton.', 'translation': "Onu o vahşi ormandan alıkoyan tek bir zincir vardı: John Thornton'a beslediği o hırçın ve şefkatli sevgi.", 'notes': 'held him back: onu alıkoydu.'}]}, {'page_no': 19, 'title': 'The Rapids of Forty Mile Creek', 'tr_title': "Forty Mile Deresi'nin Azgın Suları ve Hayat Kurtaran Atlayış", 'vocab_focus': [('rapids', 'çağlayan, azgın nehir suları'), ('churn', 'köpürmek, çalkalanmak'), ('strangle', 'boğulmak'), ('lifeline', 'can halatı, kurtarma ipi'), ('torrents', 'sel gibi akan coşkun sular'), ('bruise', 'morartmak, ezmek'), ('heroism', 'kahramanlık'), ('rescue', 'kurtarmak')], 'sentences': [{'id': 361, 'text': "Thornton's partners, Hans and Pete, arrived with a long raft loaded with supplies.", 'translation': "Thornton'ın ortakları Hans ve Pete, erzakla yüklü uzun bir salla çıkageldiler.", 'notes': 'long raft: uzun sal.'}, {'id': 362, 'text': 'Buck refused to notice them at first, but accepted them once he saw they were true friends of Thornton.', 'translation': "Buck ilk başta onları görmezden geldi, fakat Thornton'ın hakiki dostları olduklarını görünce onları kabullendi.", 'notes': 'refused to notice: görmezden geldi.'}, {'id': 363, 'text': 'In the autumn they journeyed toward the mouth of the Tanana River on their prospecting quest.', 'translation': "Sonbaharda maden arama yolculuklarında Tanana Nehri'nin ağzına doğru yola koyuldular.", 'notes': 'prospecting quest: maden arama seferi.'}, {'id': 364, 'text': 'While shooting the dangerous rapids of Forty Mile Creek, their boat was hurled against a submerged rock.', 'translation': "Forty Mile Deresi'nin tehlikeli çağlayanlarından geçerken botları su altındaki bir kayaya çarptı.", 'notes': 'shooting the rapids: çağlayandan hızla geçmek.'}, {'id': 365, 'text': 'The boat capsized, and Thornton was flung into the churning white foam of the raging waters.', 'translation': 'Bot alabora oldu ve Thornton azgın suların köpüren beyaz dalgalarının içine savruldu.', 'notes': 'capsized: alabora oldu / devrildi.'}, {'id': 366, 'text': 'He was swept toward the deadly cataract, clutching desperately to a slippery rock in mid-stream.', 'translation': 'Akıntının ortasında kaygan bir kayaya delicesine tutunarak ölümcül şelaleye doğru sürüklendi.', 'notes': 'deadly cataract: ölümcül şelale.'}, {'id': 367, 'text': 'From the bank, Buck gave a magnificent roar and plunged headlong into the torrent.', 'translation': 'Kıyıdan Buck görkemli bir kükreme kopardı ve balıklama o coşkun sele atladı.', 'notes': 'plunged headlong: balıklama daldı.'}, {'id': 368, 'text': 'He fought the rushing waves with furious strength, swimming straight toward the rock.', 'translation': 'Doğrudan kayaya doğru yüzerek hırçın dalgalarla çılgınca bir güçle savaştı.', 'notes': 'furious strength: azgın güç.'}, {'id': 369, 'text': 'He reached Thornton, and the man grabbed his thick furry neck with both hands.', 'translation': "Thornton'a ulaştı ve adam iki eliyle köpeğin kalın tüylü boynuna sımsıkı tutundu.", 'notes': 'thick furry neck: kalın tüylü boyun.'}, {'id': 370, 'text': '"Hold on, Buck! Go for the bank!" Thornton shouted above the roar of the water.', 'translation': '"Dayan Buck! Kıyıya doğru yüz!" diye bağırdı Thornton suların uğultusunun üzerinden.', 'notes': 'above the roar: uğultunun üzerinden.'}, {'id': 371, 'text': 'The terrible current tore Thornton from his grip, sweeping the man downstream toward the falls.', 'translation': "Korkunç akıntı Thornton'ı köpeğin tutuşundan kopardı ve adamı şelaleye doğru aşağı sürükledi.", 'notes': 'tore from grip: tutuşundan kopardı.'}, {'id': 372, 'text': 'Thornton managed to catch a second rock, but his strength was rapidly failing in the freezing water.', 'translation': 'Thornton ikinci bir kayayı yakalamayı başardı, fakat dondurucu suda gücü hızla tükeniyordu.', 'notes': 'strength rapidly failing: gücü hızla tükenen.'}, {'id': 373, 'text': 'Buck was hauled ashore by Hans and Pete, bruised and coughing water upon the pebbles.', 'translation': 'Hans ve Pete tarafından kıyıya çekilen Buck çakılların üzerinde ezik içinde ve su öksürerek yattı.', 'notes': 'hauled ashore: kıyıya çekildi.'}, {'id': 374, 'text': "They tied a stout rope around Buck's shoulders and chest, knotted securely to prevent slipping.", 'translation': "Kaymasını önlemek için sağlam düğümlerle Buck'ın omuzlarına ve göğsüne kalın bir halat bağladılar.", 'notes': 'stout rope: sağlam halat.'}, {'id': 375, 'text': "Without an instant's hesitation, Buck plunged back into the foaming abyss.", 'translation': 'Tek bir saniye dahi tereddüt etmeden Buck o köpüren girdabın içine tekrar atladı.', 'notes': "without an instant's hesitation: tek an tereddüt etmeden."}, {'id': 376, 'text': 'He missed the rock on his first pass, but swam with superhuman determination on the second attempt.', 'translation': 'İlk geçişinde kayayı ıskaladı, fakat ikinci denemede insanüstü bir azimle yüzdü.', 'notes': 'superhuman determination: insanüstü azim.'}, {'id': 377, 'text': "He crashed against the rock, and Thornton locked both arms around the great dog's neck.", 'translation': 'Kayaya var gücüyle çarptı ve Thornton iki kolunu koca köpeğin boynuna kilitledi.', 'notes': 'locked arms: kollarını kilitledi.'}, {'id': 378, 'text': 'Hans and Pete hauled upon the rope from the shore with all their combined muscle.', 'translation': 'Hans ve Pete kıyıdan bütün güçlerini birleştirerek halata var güçleriyle asıldılar.', 'notes': 'hauled upon: asıldılar.'}, {'id': 379, 'text': 'They were dragged through the boiling rapids, battered against jagged boulders, but they reached the bank alive.', 'translation': 'Kaynayan çağlayanların içinden çekildiler, sivri kayalara çarptılar, fakat kıyıya canlı ulaştılar.', 'notes': 'jagged boulders: sivri kayalar.'}, {'id': 380, 'text': 'Buck had three broken ribs from the rescue, but Thornton wept tears of joy as he bandaged his saviour.', 'translation': "Bu kurtarıştan ötürü Buck'ın üç kaburgası kırılmıştı, fakat kurtarıcısını sararken Thornton sevinç gözyaşları döktü.", 'notes': 'bandaged his saviour: kurtarıcısını sardı.'}]}, {'page_no': 20, 'title': 'The Thousand-Pound Bet in Dawson', 'tr_title': "Dawson'daki Büyük Bahis: Bin Poundluk Donmuş Kızak", 'vocab_focus': [('wager', 'bahis, iddia'), ('feat', 'büyük başarı, hüner'), ('frozen', 'donmuş, buza yapışmış'), ('crowd', 'kalabalık'), ('flour', 'un'), ('strain', 'zorlamak, olanca gücüyle asılmak'), ('triumph', 'zafer'), ('fabulous', 'muazzam, inanılmaz')], 'sentences': [{'id': 381, 'text': 'That winter at Dawson, Buck performed an exploit that became legendary throughout the entire Klondike.', 'translation': "O kış Dawson'da Buck, tüm Klondike boyunca efsanelere konu olan bir kahramanlık sergiledi.", 'notes': 'performed an exploit: bir hüner/kahramanlık sergiledi.'}, {'id': 382, 'text': 'In the Eldorado Saloon, several wealthy miners were boasting of the strength of their favourite dogs.', 'translation': "Eldorado Saloon'da birkaç zengin madenci, en gözde köpeklerinin gücüyle övünüyordu.", 'notes': 'boasting of: ile övünerek.'}, {'id': 383, 'text': 'One man claimed his dog could break out a sled weighing five hundred pounds.', 'translation': 'Bir adam köpeğinin beş yüz poundluk donmuş bir kızağı yerinden sökebileceğini iddia etti.', 'notes': 'break out: dondan söküp kurtarmak.'}, {'id': 384, 'text': '"Buck can break out a thousand pounds and walk off with it for a hundred yards!" Thornton declared proudly.', 'translation': '"Buck bin poundluk donmuş kızağı yerinden söker ve onunla yüz yarda yürür!" diye gururla bildirdi Thornton.', 'notes': 'walk off with: alıp yürümek.'}, {'id': 385, 'text': '"A thousand pounds? Put up your money!" cried Matthewson, a rich Bonanza King.', 'translation': '"Bin pound mu? Koy paranı ortaya!" diye haykırdı zengin bir maden kralı olan Matthewson.', 'notes': 'put up your money: paranı ortaya koy.'}, {'id': 386, 'text': 'Matthewson placed a sack of gold dust worth one thousand dollars upon the bar counter.', 'translation': 'Matthewson bar tezgahının üzerine bin dolar değerinde bir altın tozu kesesi koydu.', 'notes': 'sack of gold dust: altın tozu kesesi.'}, {'id': 387, 'text': "Thornton had no such money, but his friend Jim O'Brien loaned him the gold on faith in Buck.", 'translation': "Thornton'ın o kadar parası yoktu, fakat dostu Jim O'Brien Buck'a olan inancıyla ona altını borç verdi.", 'notes': 'on faith: güvenerek.'}, {'id': 388, 'text': 'A crowd of several hundred miners poured out into the street to witness the impossible wager.', 'translation': 'Birkaç yüz madenciden oluşan bir kalabalık, bu imkansız bahse tanıklık etmek için sokağa döküldü.', 'notes': 'poured out: sokağa döküldü.'}, {'id': 389, 'text': "Matthewson's sled stood outside, loaded with twenty fifty-pound sacks of flour, frozen fast to the snow.", 'translation': "Matthewson'ın kızağı dışarıda duruyordu; yirmi adet elli poundluk un çuvalıyla yüklüydü ve kara donup yapışmıştı.", 'notes': 'sacks of flour: un çuvalları.'}, {'id': 390, 'text': 'The temperature was sixty degrees below zero, and the runners had gripped the ice for two hours.', 'translation': 'Hava sıcaklığı sıfırın altında altmış dereceydi ve kızak ayakları iki saattir buza kilitlenmişti.', 'notes': 'gripped the ice: buzu kavramış/yapışmıştı.'}, {'id': 391, 'text': "Odds of two-to-one and three-to-one were freely offered against Buck's chances.", 'translation': "Buck'ın şansına karşı ikiye bir ve üçe bir oranında bahisler serbestçe açıldı.", 'notes': 'odds: bahis oranları.'}, {'id': 392, 'text': 'Buck was harnessed alone to the monster sled, looking confident and magnificent in the snow.', 'translation': 'Buck karların içinde kendinden emin ve görkemli görünerek o devasa kızağa tek başına koşuldu.', 'notes': 'harnessed alone: tek başına koşuldu.'}, {'id': 393, 'text': 'Thornton knelt beside him, took his head in his hands, and whispered: "As you love me, Buck. As you love me."', 'translation': 'Thornton yanına diz çöktü, başını ellerinin arasına aldı ve fısıldadı: "Beni sevdiğin gibi Buck. Beni sevdiğin hatırına."', 'notes': 'as you love me: beni sevdiğin gibi.'}, {'id': 394, 'text': 'Buck whined with suppressed passion, his muscles trembling beneath his thick furry coat.', 'translation': 'Buck bastırılmış bir tutkuyla inledi; kalın kürkünün altındaki kasları heyecandan titriyordu.', 'notes': 'suppressed passion: bastırılmış tutku.'}, {'id': 395, 'text': 'Thornton stood back and shouted the command: "Now, Buck! Gee!"', 'translation': 'Thornton geriye çekildi ve komutu haykırdı: "Şimdi Buck! Sağa!"', 'notes': 'gee: sağa çekme komutu.'}, {'id': 396, 'text': 'Buck threw his weight to the right, breaking the frozen grip on that side with a sharp crack.', 'translation': 'Buck ağırlığını sağa verdi; o taraftaki donmuş kilidi keskin bir çatırtıyla kırdı.', 'notes': 'sharp crack: keskin çatırtı.'}, {'id': 397, 'text': '"Haw!" shouted Thornton, and Buck swung to the left, breaking the other runner completely free.', 'translation': '"Sola!" diye bağırdı Thornton; Buck sola yüklendi ve diğer kızak ayağını da buzdan tamamen kurtardı.', 'notes': 'haw: sola çekme komutu.'}, {'id': 398, 'text': '"Now, MUSH!" roared Thornton, and Buck threw himself into the breast-band with all his soul.', 'translation': '"Şimdi, DEH!" diye kükredi Thornton; Buck bütün ruhuyla göğüs kayışına asıldı.', 'notes': 'threw into breast-band: göğüs kayışına var gücüyle asıldı.'}, {'id': 399, 'text': 'His claws gripped the ice, his muscles stood out like steel cables, and inch by inch the sled began to move.', 'translation': 'Pençeleri buza kenetlendi, kasları çelik halatlar gibi kabardı ve kızak santim santim hareket etmeye başladı.', 'notes': 'steel cables: çelik halatlar.'}, {'id': 400, 'text': 'The crowd held its breath as the great dog hauled the thousand pounds across the line, winning the wager!', 'translation': 'O koca köpek bin poundu çizginin karşısına çekip bahsi kazanırken kalabalık nefesini tuttu!', 'notes': 'held breath: nefesini tuttu.'}]}, {'page_no': 21, 'title': 'The Lost Cabin and the Gold Creek', 'tr_title': 'Kayıp Kulübe, Altın Deresi ve Ormanın Derin Çağrısı', 'vocab_focus': [('nugget', 'külçe altın'), ('placer', 'altın yatağı, alüvyon'), ('trough', 'tekne, yıkama teknesi'), ('wilderness', 'el değmemiş doğa'), ('primitive', 'ilkel, el değmemiş'), ('beckon', 'çağırmak, el etmek'), ('restless', 'huzursuz, yerinde duramaz'), ('brotherhood', 'kardeşlik')], 'sentences': [{'id': 401, 'text': 'With the sixteen hundred dollars won by Buck, Thornton paid off his debts and bought complete supplies.', 'translation': "Buck'ın kazandırdığı bin altı yüz dolarla Thornton borçlarını ödedi ve eksiksiz erzak satın aldı.", 'notes': 'paid off debts: borçlarını kapattı.'}, {'id': 402, 'text': 'Together with Hans and Pete, he set out into the uncharted wilderness to find a fabled lost mine.', 'translation': 'Hans ve Pete ile birlikte efsanevi bir kayıp altın madenini bulmak için haritalandırılmamış yaban hayatına çıktılar.', 'notes': 'uncharted: haritasız, keşfedilmemiş.'}, {'id': 403, 'text': 'For months they travelled east into country where no white man had ever trodden before.', 'translation': 'Aylarca doğuya doğru, daha önce hiçbir beyaz adamın ayak basmadığı topraklara ilerlediler.', 'notes': 'had ever trodden: ayak basmıştı.'}, {'id': 404, 'text': 'They lived by the rifle and the fishing net, traversing valleys and scaling untamed mountain ranges.', 'translation': 'Tüfekle ve balık ağıyla geçindiler; vadileri aşıp vahşi dağ silsilelerine tırmandılar.', 'notes': 'untamed: evcilleşmemiş, el değmemiş.'}, {'id': 405, 'text': 'In the spring they stumbled upon a broad valley where gold dust coated the gravel like butter.', 'translation': 'İlkbaharda, altın tozunun çakılları tereyağı gibi kapladığı geniş bir vadiye denk geldiler.', 'notes': 'stumbled upon: tesadüfen rastladı.'}, {'id': 406, 'text': 'Every washing pan revealed handfuls of pure yellow gold, richer than their wildest dreams.', 'translation': 'Her yıkama leğeni, en çılgın rüyalarından bile daha zengin olan avuç dolusu saf sarı altını açığa çıkardı.', 'notes': 'wildest dreams: en çılgın hayaller.'}, {'id': 407, 'text': 'They built a comfortable log cabin and spent long sunny days shoveling gravel and stacking gold bags.', 'translation': 'Rahat bir kütük kulübe inşa ettiler ve çakıl küreyip altın torbalarını yığarak uzun güneşli günler geçirdiler.', 'notes': 'stacking: istifleyerek.'}, {'id': 408, 'text': 'For Buck, there was no work to do; he was free to wander wherever his wild fancy took him.', 'translation': 'Buck için yapacak hiçbir iş yoktu; vahşi hevesi onu nereye çekerse oraya dolaşmakta özgürdü.', 'notes': 'wherever his fancy took him: hevesi nereye çekerse.'}, {'id': 409, 'text': 'He roamed through the ancient forests, chasing squirrels and bathing in clear alpine pools.', 'translation': 'Sincapları kovalayarak ve berrak dağ havuzlarında yıkanarak kadim ormanlarda gezindi.', 'notes': 'alpine pools: yüksek dağ göletleri.'}, {'id': 410, 'text': 'Yet deep within his soul, the mysterious call from the heart of the forest grew louder each day.', 'translation': 'Yine de ruhunun derinliklerinde, ormanın kalbinden gelen o gizemli çağrı her geçen gün daha gür çıkıyordu.', 'notes': 'grew louder: daha da yükseldi.'}, {'id': 411, 'text': 'It was a wild, compelling summons that filled him with unutterable longings.', 'translation': 'Onu tarif edilemez özlemlerle dolduran vahşi, karşı konulmaz bir çağrıydı bu.', 'notes': 'unutterable longings: kelimelere dökülemez özlemler.'}, {'id': 412, 'text': 'He would start up from his sleep, his ears erect, listening to something only he could hear.', 'translation': 'Kulakları dikilmiş vaziyette uykusundan sıçrar; yalnızca kendisinin duyabildiği bir şeyi dinlerdi.', 'notes': 'ears erect: kulakları dikilmiş.'}, {'id': 413, 'text': 'One night he slipped away from the camp and plunged into the darkened woods.', 'translation': 'Bir gece kamptan usulca sıvıştı ve kararan ormanın içine daldı.', 'notes': 'slipped away: sessizce sıvıştı.'}, {'id': 414, 'text': 'A long, mournful howl rose through the trees, vibrating through his very bones.', 'translation': 'Ağaçların arasından uzun, hüzünlü bir uluma yükseldi; iliklerine kadar onu titretti.', 'notes': 'vibrating through bones: kemiklerine kadar titreten.'}, {'id': 415, 'text': 'He ran toward the sound, leaping through the brush with silent, predatory grace.', 'translation': 'Sessiz, yırtıcı bir zarafetle çalıların arasından sıçrayarak sese doğru koştu.', 'notes': 'predatory grace: avcı zarafeti.'}, {'id': 416, 'text': 'In an open glade, nose pointed at the stars, sat a lean timber wolf singing to the moon.', 'translation': 'Açık bir orman çayırında burnunu yıldızlara dikmiş zayıf bir kır kurdu aya doğru şarkı söylüyordu.', 'notes': 'lean timber wolf: zayıf orman kurdu.'}, {'id': 417, 'text': 'Buck stepped forward softly, his tail low, wishing to make contact with his wild brother.', 'translation': 'Vahşi kardeşiyle temas kurmak isteyerek kuyruğu aşağıda, Buck usulca öne adım attı.', 'notes': 'stepped forward softly: yumuşakça öne adım attı.'}, {'id': 418, 'text': 'The wolf caught his scent, turned like a flash, and fled terrified through the timber.', 'translation': 'Kurt onun kokusunu aldı, şimşek gibi döndü ve dehşet içinde ormanın içinden kaçtı.', 'notes': 'caught scent: kokusunu aldı.'}, {'id': 419, 'text': 'Buck pursued him effortlessly, his long, effortless strides matching the wild beast mile after mile.', 'translation': 'Miller boyunca o vahşi hayvanın hızına ayak uydurarak uzun, zahmetsiz adımlarıyla Buck onu kolayca takip etti.', 'notes': 'effortless strides: zahmetsiz adımlar.'}, {'id': 420, 'text': 'At last he cornered the wolf in a rocky creek bed, where the wild creature turned to fight.', 'translation': 'Nihayetinde kurdu kayalık bir dere yatağında sıkıştırdı; orada vahşi yaratık dövüşmek için geri döndü.', 'notes': 'cornered: köşeye sıkıştırdı.'}]}, {'page_no': 22, 'title': 'The Night Hunt and the Timber Wolf', 'tr_title': 'Gece Avı ve Gri Kurtla İlk Dostluk Koşusu', 'vocab_focus': [('snarl', 'diş gösterip hırlamak'), ('fraternal', 'kardeşçe, dostane'), ('playful', 'oyuncu, şakacı'), ('romp', 'neşeyle oynaşmak'), ('kinsman', 'akraba, soydaş'), ('dilemma', 'ikilem, çelişki'), ('yearning', 'özlem, derin arzu'), ('communion', 'yakın bağ, ruh birliği')], 'sentences': [{'id': 421, 'text': 'The timber wolf snarled fiercely, his hackles raised, ready to die fighting.', 'translation': 'Yeleleri kabarmış orman kurdu dövüşerek ölmeye hazır halde vahşice hırladı.', 'notes': 'hackles raised: yeleleri kabarmış.'}, {'id': 422, 'text': 'Buck did not attack; he circled gently, making friendly, fraternal overtures.', 'translation': 'Buck saldırmadı; dostane, kardeşçe yaklaşımlarda bulunarak etrafında sakince döndü.', 'notes': 'fraternal overtures: kardeşçe yaklaşımlar.'}, {'id': 423, 'text': "Gradually, the wolf ceased his growling and cautiously sniffed Buck's outstretched muzzle.", 'translation': "Zamanla kurt hırlamasını kesti ve temkinle Buck'ın uzattığı burnunu kokladı.", 'notes': 'outstretched muzzle: uzatılmış burun.'}, {'id': 424, 'text': 'In a moment, suspicion vanished, and they romped together upon the forest floor like playful puppies.', 'translation': 'Bir anda şüphe yok oldu ve orman zemininde oyuncu enikler gibi birlikte neşeyle oynaştılar.', 'notes': 'romped together: birlikte oynaştılar.'}, {'id': 425, 'text': 'Side by side they ran through the moonlit woods, leaping fallen logs and splashing through streams.', 'translation': 'Ay ışığının aydınlattığı ormanda yan yana koştular; devrilmiş kütüklerin üzerinden atlayıp derelerden geçtiler.', 'notes': 'side by side: yan yana.'}, {'id': 426, 'text': 'Buck was intoxicated with wild joy; he was running with his own kind at last.', 'translation': 'Buck vahşi bir sevinçle sarhoş olmuştu; nihayet kendi soyuyla birlikte koşuyordu.', 'notes': 'intoxicated with joy: sevinçten sarhoş.'}, {'id': 427, 'text': 'He was a wolf among wolves, responding to the ancient blood that sang in his veins.', 'translation': 'Kurtların arasında bir kurttu artık; damarlarında ezgisini söyleyen o kadim kana karşılık veriyordu.', 'notes': 'ancient blood: kadim kan.'}, {'id': 428, 'text': 'They ran for miles, until the wolf turned toward the wild mountains, beckoning Buck to follow.', 'translation': "Millerce koştular; ta ki kurt vahşi dağlara doğru dönüp Buck'a kendisini takip etmesini işaret edene dek.", 'notes': 'beckoning to follow: takip etmesi için işaret eden.'}, {'id': 429, 'text': 'Buck halted; a vision of John Thornton rose before his eyes.', 'translation': "Buck durdu; gözlerinin önünde John Thornton'ın hayali canlandı.", 'notes': 'vision rose: hayal belirdi.'}, {'id': 430, 'text': "The memory of the man's warm hands and gentle voice tugged painfully at his heartstrings.", 'translation': 'O adamın sıcak ellerinin ve nazik sesinin hatırası yürek tellerini acıyla sızlattı.', 'notes': 'tugged at heartstrings: yürek tellerini sızlattı.'}, {'id': 431, 'text': 'He turned back and trotted slowly toward the cabin, though his heart was torn in two.', 'translation': 'Yüreği ikiye bölünmüş olsa da arkasını döndü ve kulübeye doğru yavaşça tırıs gitti.', 'notes': 'heart was torn: yüreği ikiye bölünmüştü.'}, {'id': 432, 'text': 'Thornton was eating breakfast when Buck leaped into camp, overwhelming the man with wild demonstrations of affection.', 'translation': 'Buck kampa dalıp adamı vahşi sevgi gösterilerine boğduğunda Thornton kahvaltı ediyordu.', 'notes': 'overwhelming with affection: sevgiye boğarak.'}, {'id': 433, 'text': "For two days he never left Thornton's side, watching his every movement with frantic devotion.", 'translation': "İki gün boyunca Thornton'ın yanından hiç ayrılmadı; onun her hareketini çılgınca bir sadakatle izledi.", 'notes': 'frantic devotion: çılgınca sadakat.'}, {'id': 434, 'text': "He followed him everywhere, sleeping with his head upon the man's knees.", 'translation': 'Onu her yerde takip etti; başı adamın dizlerinin üzerinde uyudu.', 'notes': 'followed everywhere: her yerde izledi.'}, {'id': 435, 'text': 'Yet the restlessness soon returned, pulling his gaze toward the dark, silent forest.', 'translation': 'Fakat o huzursuzluk çok geçmeden geri döndü; bakışlarını o karanlık, sessiz ormana doğru çekerek.', 'notes': 'restlessness returned: huzursuzluk geri döndü.'}, {'id': 436, 'text': 'He began to hunt larger game alone, testing his strength against the fierce inhabitants of the wild.', 'translation': 'Vahşi doğanın çetin sakinlerine karşı gücünü sınayarak tek başına daha büyük avların peşine düşmeye başladı.', 'notes': 'larger game: daha büyük av.'}, {'id': 437, 'text': 'He killed a black bear in a savage battle, leaving the carcass for the ravens.', 'translation': 'Vahşi bir savaşta siyah bir ayıyı öldürdü; leşini kuzgunlara bıraktı.', 'notes': 'carcass: hayvan leşi.'}, {'id': 438, 'text': 'He caught salmon in the roaring rapids with the skill of a native otter.', 'translation': 'Yerli bir su samurunun ustalığıyla kükreyen çağlayanlarda somon balığı yakaladı.', 'notes': 'skill of an otter: su samuru becerisi.'}, {'id': 439, 'text': 'He was a killer, a lord of the wilderness, fearing no beast that walked or crept.', 'translation': 'O bir avcıydı, yaban hayatının efendisiydi; yürüyen veya sürünen hiçbir hayvandan korkmuyordu.', 'notes': 'lord of the wilderness: yaban hayatının efendisi.'}, {'id': 440, 'text': 'And then came the supreme hunting test that would crown him master of the northern forests.', 'translation': 'Ve ardından onu kuzey ormanlarının efendisi olarak taçlandıracak o en yüce av sınavı çıkageldi.', 'notes': 'supreme test: en yüce sınav.'}]}, {'page_no': 23, 'title': 'Slaying the Great Bull Moose', 'tr_title': 'Büyük Sığın Geyiğinin Tek Başına Avlanması', 'vocab_focus': [('moose', 'sığın, büyük boynuzlu geyik'), ('antler', 'geyik boynuzu'), ('relentless', 'amansız, dur durak bilmez'), ('quarry', 'av, peşine düşülen av'), ('exhaustion', 'bitkinlik, dermansızlık'), ('perseverance', 'azim, sebat'), ('patience', 'sabır'), ('slay', 'katletmek, avlamak')], 'sentences': [{'id': 441, 'text': 'In the late autumn, a great herd of moose moved through the valley, seeking lower winter pastures.', 'translation': 'Sonbahar sonlarında büyük bir sığın geyiği sürüsü daha alçak kış otlaklarını arayarak vadiden geçti.', 'notes': 'great herd: büyük sürü.'}, {'id': 442, 'text': 'At their head marched a magnificent bull moose, standing seven feet high at the shoulder.', 'translation': 'Başlarında omuz yüksekliği yedi fiti bulan muazzam bir erkek sığın geyiği yürüyordu.', 'notes': 'bull moose: erkek sığın geyiği.'}, {'id': 443, 'text': 'He possessed an enormous span of branched antlers, and his wicked little eyes blazed with savage fury.', 'translation': 'Çatallı boynuzlardan oluşan devasa bir açıklığa sahipti ve hırçın küçük gözleri vahşi bir öfkeyle parlıyordu.', 'notes': 'branched antlers: çatallı boynuzlar.'}, {'id': 444, 'text': 'An arrow protruding from his flank showed that hunters had wounded him, making him doubly dangerous.', 'translation': 'Böğründen dışarı sarkan bir ok avcıların onu yaraladığını gösteriyordu; bu da onu iki kat tehlikeli kılıyordu.', 'notes': 'protruding: dışarı fırlamış.'}, {'id': 445, 'text': 'Buck resolved to cut this monarch from the herd and bring him down single-handed.', 'translation': 'Buck bu hükümdarı sürüden ayırmaya ve tek başına yere sermeye ant içti.', 'notes': 'single-handed: tek başına.'}, {'id': 446, 'text': 'For four long days and nights, Buck maintained an unbroken, relentless siege upon the giant beast.', 'translation': 'Dört uzun gün ve gece boyunca Buck, bu devasa hayvanın üzerinde kesintisiz, amansız bir kuşatma sürdürdü.', 'notes': 'relentless siege: amansız kuşatma.'}, {'id': 447, 'text': 'He never let the wounded bull rest, drink, or graze for a single minute.', 'translation': 'Yaralı erkeğin tek bir dakika dahi dinlenmesine, su içmesine ya da otlamasına izin vermedi.', 'notes': 'never let rest: asla dinlendirtmedi.'}, {'id': 448, 'text': 'Whenever the moose charged, Buck leaped lithely aside; whenever he turned to escape, Buck harried his heels.', 'translation': 'Geyik ne zaman hücum etse Buck kıvrakça yana kaçtı; ne zaman kaçmaya yeltense Buck topuklarını taciz etti.', 'notes': 'harried his heels: topuklarını rahatsız etti.'}, {'id': 449, 'text': 'He was a black shadow that could not be shaken off, tireless as the falling snow.', 'translation': 'O üzerinden silkelenip atılamayan bir kara gölgeydi; yağan kar kadar yorulmazdı.', 'notes': 'could not be shaken off: silkip atılamayan.'}, {'id': 450, 'text': 'The herd marched on, leaving their dying leader behind in the clutches of the patient stalker.', 'translation': 'Sürü yola devam etti; can çekişen liderlerini sabırlı avcının pençelerinde geride bırakarak.', 'notes': 'patient stalker: sabırlı avcı.'}, {'id': 451, 'text': 'By the fourth evening, the great bull moose was staggering from pure exhaustion and blood loss.', 'translation': 'Dördüncü akşama gelindiğinde o devasa sığın geyiği katıksız bitkinlikten ve kan kaybından sendeliyordu.', 'notes': 'staggering: sendeleyen.'}, {'id': 452, 'text': 'His massive head drooped, his tongue hung out swollen, and his ferocious eyes were glazed with death.', 'translation': 'Kocaman başı öne düştü, dili şişmiş vaziyette dışarı sarktı ve vahşi gözleri ölümle donuklaştı.', 'notes': 'massive head drooped: ağır başı öne düştü.'}, {'id': 453, 'text': 'Buck sprang onto his back, sinking his fangs deep into the throat of the fallen giant.', 'translation': 'Buck onun sırtına sıçradı ve dişlerini devrilen devin gırtlağına derinlemesine geçirdi.', 'notes': 'sinking fangs: dişlerini batırarak.'}, {'id': 454, 'text': 'The bull crashed to the earth with a final shuddering groan, and Buck was victorious.', 'translation': 'Geyik son bir titreyen iniltiyle yere serildi ve Buck muzaffer oldu.', 'notes': 'shuddering groan: titreyen inilti.'}, {'id': 455, 'text': 'He feasted upon the fresh meat, rested for a day, and then felt a sudden urge to return to Thornton.', 'translation': "Taze etle ziyafet çekti, bir gün dinlendi ve ardından Thornton'a dönmek için ani bir dürtü hissetti.", 'notes': 'feasted upon: ziyafet çekti.'}, {'id': 456, 'text': 'A dark foreboding fell upon his spirit as he bounded back across the hills toward the camp.', 'translation': 'Tepeleri aşıp kampa doğru geri koşarken ruhuna karanlık bir uğursuzluk önsezisi çöktü.', 'notes': 'dark foreboding: karanlık önsezi.'}, {'id': 457, 'text': 'The wind smelled strange; a subtle scent of danger and death drifted through the trees.', 'translation': 'Rüzgar tuhaf kokuyordu; ağaçların arasından sinsi bir tehlike ve ölüm kokusu süzülüp geliyordu.', 'notes': 'subtle scent: hafif/sinsi koku.'}, {'id': 458, 'text': 'Three miles from the cabin he found the body of Nig, pierced by feathered arrows.', 'translation': "Kulübeye üç mil kala Nig'in tüylü oklarla delik deşik edilmiş cansız bedenini buldu.", 'notes': 'pierced by arrows: oklarla delinmiş.'}, {'id': 459, 'text': 'A hundred yards further lay one of the sled dogs, dying in the blood-soaked moss.', 'translation': 'Yüz yarda ileride kızak köpeklerinden biri kana bulanmış yosunların üzerinde can çekişiyordu.', 'notes': 'blood-soaked moss: kana doymuş yosun.'}, {'id': 460, 'text': 'Buck leaped forward with lightning speed, a terrifying rage boiling in every vein of his body.', 'translation': 'Bedeninin her bir damarında korkunç bir öfke kaynayarak Buck şimşek hızıyla öne fırladı.', 'notes': 'boiling rage: kaynayan gazap.'}]}, {'page_no': 24, 'title': 'The Tragedy of the Yeehats', 'tr_title': "Yeehat Baskını, Thornton'ın Ölümü ve Buck'ın Dehşetli İntikamı", 'vocab_focus': [('carnage', 'katliam, kıyım'), ('ferocious', 'yırtıcı, dehşet saçan'), ('vengeance', 'intikam, öç'), ('slaughter', 'boğazlamak, katletmek'), ('mournful', 'hüzünlü, kederli'), ('demon', 'ifrit, iblis'), ('grief', 'büyük acı, keder'), ('sever', 'koparmak, kesmek')], 'sentences': [{'id': 461, 'text': 'Buck burst into the clearing and beheld a scene of horrific devastation.', 'translation': 'Buck orman açıklığına daldı ve korkunç bir yıkım manzarasıyla karşılaştı.', 'notes': 'horrific devastation: dehşet verici yıkım.'}, {'id': 462, 'text': 'Hans lay dead upon his face, feathered with arrows like a porcupine.', 'translation': 'Hans, bir kirpi gibi oklarla bezenmiş vaziyette yüzüstü ölü yatıyordu.', 'notes': 'feathered with arrows: oklarla donanmış.'}, {'id': 463, 'text': 'About the ruined cabin, a score of Yeehat Indians were dancing a wild victory dance.', 'translation': 'Harap olmuş kulübenin etrafında yirmi kadar Yeehat yerlisi vahşi bir zafer dansı yapıyordu.', 'notes': 'victory dance: zafer dansı.'}, {'id': 464, 'text': 'At that moment, all restraint fell from Buck, and he became an incarnation of absolute fury.', 'translation': "O anda Buck'ın tüm dizginleri koptu ve mutlak bir gazabın canlı timsaline dönüştü.", 'notes': 'incarnation of fury: öfkenin beden bulmuş hali.'}, {'id': 465, 'text': 'He hurled himself into the midst of the Indians like a raging cyclone of fangs and claws.', 'translation': 'Dişlerden ve pençelerden oluşan kükreyen bir kasırga gibi yerlilerin ortasına daldı.', 'notes': 'raging cyclone: kükreyen kasırga.'}, {'id': 466, 'text': "He plunged straight at the chief's throat, ripping open the jugular vein with a single snap.", 'translation': 'Dosdoğru şefin gırtlağına atıldı; tek bir ısırışla şahdamarını boydan boya yardı.', 'notes': 'jugular vein: şahdamarı.'}, {'id': 467, 'text': 'He leaped from throat to throat, tearing, slashing, and destroying with blinding speed.', 'translation': 'Göz açıp kapayıncaya kadar bir hızla gırtlaktan gırtlağa sıçradı; parçalayarak, keserek ve yok ederek.', 'notes': 'blinding speed: göz kamaştırıcı hız.'}, {'id': 468, 'text': 'The Indians could not defend themselves; arrows pierced their own comrades in the wild panic.', 'translation': 'Yerliler kendilerini savunamadılar; o vahşi panikte oklar kendi yoldaşlarını delip geçti.', 'notes': 'wild panic: vahşi panik.'}, {'id': 469, 'text': 'They believed him to be an evil Fiend, the Ghost Dog of the woods, invincible and immortal.', 'translation': 'Onun ormanın İblisi, yenilmez ve ölümsüz Hayalet Köpek olduğuna inandılar.', 'notes': 'evil Fiend: kötücül ifrit/şeytan.'}, {'id': 470, 'text': 'Shrieking in terror, the surviving Yeehats fled into the forest, never to return to that valley.', 'translation': 'Dehşet içinde çığlıklar atarak hayatta kalan Yeehatlar o vadiye bir daha asla dönmemek üzere ormana kaçtılar.', 'notes': 'shrieking in terror: dehşetle çığlık atarak.'}, {'id': 471, 'text': "Buck followed Thornton's scent to the edge of the deep pool in the creek.", 'translation': "Buck Thornton'ın kokusunu deredeki derin göletin kıyısına kadar takip etti.", 'notes': 'edge of the deep pool: derin havuzun kenarı.'}, {'id': 472, 'text': "Skeet lay dead at the water's edge, faithful to the end.", 'translation': 'Sonuna kadar sadık kalan Skeet suyun kenarında ölü yatıyordu.', 'notes': 'faithful to the end: sonuna kadar sadık.'}, {'id': 473, 'text': 'In the murky depths beneath the surface lay John Thornton, lifeless and still.', 'translation': 'Yüzeyin altındaki bulanık derinliklerde John Thornton cansız ve hareketsiz yatıyordu.', 'notes': 'murky depths: bulanık derinlikler.'}, {'id': 474, 'text': 'Buck curled himself by the edge of the pool, overwhelmed by an abyss of grief.', 'translation': 'Uçsuz bucaksız bir keder uçurumuna gömülen Buck havuzun kenarına kıvrılıp yattı.', 'notes': 'abyss of grief: keder uçurumu.'}, {'id': 475, 'text': 'All day he lay motionless, mourning the only human he had ever truly loved.', 'translation': 'Bütün gün hareketsiz yattı; gerçekten sevdiği tek insanın yasını tutarak.', 'notes': 'mourning: yas tutarak.'}, {'id': 476, 'text': 'The last tie that bound him to the world of men was broken forever.', 'translation': 'Onu insanların dünyasına bağlayan son bağ da sonsuza dek kopmuştu.', 'notes': 'last tie was broken: son bağ koptu.'}, {'id': 477, 'text': 'He had killed man, the lawgiver with the club, and found that man was easy to destroy.', 'translation': 'O sopalı kanun koyucu insanı öldürmüş ve insanın yok edilmesinin pek kolay olduğunu görmüştü.', 'notes': 'easy to destroy: yok etmesi kolay.'}, {'id': 478, 'text': 'Night came on, and the full moon rose above the timber, flooding the glade with pale light.', 'translation': 'Gece çöktü ve dolunay ormanın üzerinde yükselerek açıklığı solgun bir ışıkla doldurdu.', 'notes': 'flooding with light: ışıkla doldurarak.'}, {'id': 479, 'text': 'From the distance came the calling voices of a great wolf pack hunting down the creek.', 'translation': 'Uzaktan, derenin aşağısında avlanan büyük bir kurt sürüsünün çağıran sesleri geldi.', 'notes': 'calling voices: çağıran sesler.'}, {'id': 480, 'text': 'Buck stood up, shook the dust from his heavy coat, and walked out into the moonlight.', 'translation': 'Buck ayağa kalktı, kalın kürkündeki tozu silkeledi ve ay ışığına doğru adım attı.', 'notes': 'walked out: dışarı adım attı.'}]}, {'page_no': 25, 'title': 'The Ghost Dog of the Klondike', 'tr_title': "Klondike'ın Hayalet Köpeği ve Kurt Sürüsünün Başı", 'vocab_focus': [('pack', 'kurt sürüsü'), ('chieftain', 'önder, sürü lideri'), ('legend', 'efsane, rivayet'), ('ghost', 'hayalet'), ('howl', 'ulumak, kurt uluması'), ('heritage', 'miras'), ('sovereignty', 'egemenlik, hakimiyet'), ('untamed', 'vahşi, ehlileşmemiş')], 'sentences': [{'id': 481, 'text': 'The wolf pack poured into the clearing like a grey flood, stopping dead at the sight of the giant dog.', 'translation': 'Kurt sürüsü gri bir sel gibi orman açıklığına aktı; o dev köpeği görünce olduğu yerde mıhlanıp kaldı.', 'notes': 'stopping dead: olduğu yerde çakılmak.'}, {'id': 482, 'text': 'Buck stood motionless, silent, towering over the largest wolf among them.', 'translation': 'Buck aralarındaki en iri kurttan bile daha heybetli, sessiz ve hareketsizce dikildi.', 'notes': 'towering over: tepesinde heybetle yükselerek.'}, {'id': 483, 'text': 'A bold wolf leaped forward to strike, but Buck snapped his neck with a single crushing bite.', 'translation': 'Cesur bir kurt vurmak için öne fırladı, fakat Buck tek bir ezici ısırıkla onun boynunu kırdı.', 'notes': 'crushing bite: ezici ısırış.'}, {'id': 484, 'text': "Three others charged together, and three times Buck's lightning fangs slashed open their throats.", 'translation': "Diğer üçü birlikte saldırdı ve üç defa Buck'ın şimşek gibi dişleri onların gırtlaklarını yardı.", 'notes': 'slashed open: yarıp açtı.'}, {'id': 485, 'text': 'Then a lean, grey timber wolf stepped forward with a whimper of friendly recognition.', 'translation': 'Ardından zayıf, boz bir orman kurdu dostça bir tanıma iniltisiyle öne çıktı.', 'notes': 'friendly recognition: dostça tanıma.'}, {'id': 486, 'text': 'It was the wild brother with whom he had run beneath the moon weeks before.', 'translation': 'Haftalar önce ayın altında birlikte koştuğu o vahşi kardeşti bu.', 'notes': 'with whom he had run: birlikte koştuğu.'}, {'id': 487, 'text': "They touched noses softly, and an old, gaunt wolf sat down and raised the pack's song of fellowship.", 'translation': 'Burunlarını usulca birbirine değdirdiler ve yaşlı, zayıf bir kurt oturup sürünün kardeşlik şarkısını başlattı.', 'notes': 'song of fellowship: kardeşlik ezgisi.'}, {'id': 488, 'text': 'Buck threw back his great head and joined in the chorus, howling the ancient call of his blood.', 'translation': 'Buck o koca başını geriye attı ve koroya katıldı; kanının o kadim çağrısını uluyarak.', 'notes': 'howling the call: çağrıyı uluyarak.'}, {'id': 489, 'text': 'When the song ended, the pack turned into the forest, and Buck sprang forward to take the lead.', 'translation': 'Şarkı bittiğinde sürü ormana doğru döndü ve Buck başa geçmek için öne fırladı.', 'notes': 'take the lead: liderliği almak.'}, {'id': 490, 'text': 'He was their chieftain, the master wolf, leading his people across the wild northern wastes.', 'translation': 'O artık onların önderiydi; halkını vahşi kuzey çoraklarında yöneten başkurt olmuştu.', 'notes': 'master wolf: başkurt, lider kurt.'}, {'id': 491, 'text': 'Years passed, and a great legend grew among the Yeehat hunters about the valley of the gold creek.', 'translation': 'Yıllar geçti ve altın deresi vadisi hakkında Yeehat avcıları arasında büyük bir efsane doğdu.', 'notes': 'great legend grew: büyük efsane büyüdü.'}, {'id': 492, 'text': 'They whispered around their campfires of a Ghost Dog that ran at the head of the wolf pack.', 'translation': 'Kamp ateşlerinin etrafında, kurt sürüsünün başında koşan bir Hayalet Köpek hakkında fısıldaştılar.', 'notes': 'whispered of: hakkında fısıldaştılar.'}, {'id': 493, 'text': 'Hunters were found dead, their throats torn open, if they dared cross into his sacred domain.', 'translation': 'Onun kutsal mülküne adım atmaya cüret ettiklerinde avcılar gırtlakları parçalanmış halde ölü bulunurdu.', 'notes': 'sacred domain: kutsal mülk/diyar.'}, {'id': 494, 'text': 'They noted that the wolves of that region grew larger and heavier, with brown splashes upon their coats.', 'translation': 'O bölgenin kurtlarının kürklerinde kahverengi lekelerle daha iri ve daha ağır büyüdüklerini fark ettiler.', 'notes': 'brown splashes: kahverengi lekeler.'}, {'id': 495, 'text': 'Yet once every summer, when the wild flowers bloomed across the alpine meadows, Buck returned alone.', 'translation': 'Yine de her yaz bir kez, vahşi çiçekler dağ çayırlarında açtığında Buck oraya tek başına dönerdi.', 'notes': 'once every summer: her yaz bir kez.'}, {'id': 496, 'text': 'He came to the clearing where the ruined cabin stood by the silent yellow creek.', 'translation': 'Sessiz sarı derenin kıyısında o harap kulübenin durduğu açıklığa gelirdi.', 'notes': 'ruined cabin: harap kulübe.'}, {'id': 497, 'text': 'He stood beside the deep pool where John Thornton lay, gazing into the water in mournful silence.', 'translation': "John Thornton'ın yattığı derin göletin kenarında durur; kederli bir sessizlikle suların içine bakardı.", 'notes': 'mournful silence: yas dolu sessizlik.'}, {'id': 498, 'text': 'He gave one long, sorrowful howl that echoed across the hills before turning back to the wild.', 'translation': 'Vahşi doğaya geri dönmeden önce tepelerde yankılanan uzun, kederli bir uluma koyverirdi.', 'notes': 'sorrowful howl: kederli uluma.'}, {'id': 499, 'text': 'He had answered the call of his ancestors, reclaiming his rightful place in the primordial kingdom.', 'translation': 'O ilkçağ krallığındaki hak ettiği yeri yeniden kazanarak atalarının çağrısına karşılık vermişti.', 'notes': 'reclaiming rightful place: hakkı olan yeri geri alarak.'}, {'id': 500, 'text': 'And there he runs today, great of chest and white of fang, singing the song of the younger world.', 'translation': 'Ve o bugün de orada koşuyor; heybetli göğsü ve ak dişleriyle o genç dünyanın kadim şarkısını söyleyerek.', 'notes': 'song of the younger world: genç dünyanın şarkısı.'}]}]
